(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mi"] = {"ui":{"skip":"Peke ki ngā ihirangi","back":"← Hoki ki AI-gile","lang.button":"Reo: {name}","lang.dialog":"Kōwhiria he reo","lang.search":"Rapua ngā reo","lang.none":"Kāore he reo e ōrite","lang.notYet":"Kāore anō kia whakamāoritia ki te reo {name}","theme.aria":"Whakawhiti āhua: mārama, pōuri, pango rānei","theme.toLight":"Whakawhiti ki te āhua mārama","theme.toDark":"Whakawhiti ki te āhua pōuri","theme.toBlack":"Whakawhiti ki te āhua pango (pango tūturu, pai mō ngā mata OLED)","words.underline":"Tāroatia ēnei kupu i te whārangi","words.underlineHelp":"Whakanohoia te pere ki runga, pātōtia rānei tētahi kupu he rārangi ira tōna, kia kite ai koe i tōna tikanga.","words.col.todo":"Ngā kāri kua tīpakohia mō nāianei: ka tīmata te rōpū i ēnei i muri ake.","words.col.doing":"Kei te mahi tētahi AI i tēnei kāri i tēnei wā tonu.","words.col.review":"Kua oti i tētahi AI te mahi; ka arotake tētahi atu i mua i tana tae atu ki a koe.","words.col.verify":"E tatari ana ki a koe: whakamātauria, ka kī mai mehemea e mahi ana.","words.col.team":"Ō tuhipoka, ō whakautu rānei, e tatari ana kia tikina e te rōpū.","words.col.done":"Kua oti, kua whakaaetia hoki.","index.title":"AI-gile: tō rōpū hanga AI i runga i te papa kotahi","index.description":"He papa kanban a AI-gile mō ngā rōpū waehere AI. Ka mahi rātou i a koe e moe ana; ka toe māu he puranga poto: he mea hei whakatau, hei whakamātau, hei whakaae.","hero.logoAlt":"Tohu papa AI-gile","hero.h1.html":"Tō rōpū hanga AI, i runga i te papa&nbsp;kotahi.","hero.alpha":"🐣 Pre-alpha kati","hero.alphaTitle":"Tōmua, kāore anō kia oti: ngā mihi mō tō whakamātau!","hero.lede":"Ka hanga rātou i a koe e moe ana. Ka ara koe ki te puranga poto kotahi: ētahi pātai, ētahi mea hei whakamātau, tētahi taimana waiporoporo e rua rānei. Pāwhiri, whakaae, hoki ki tō kawhe.","dl.windows":"Taupānga Windows","dl.browser":"Whakahaerehia i tō pūtirotiro","dl.messenger":"📱 Messenger mō tō waea","dl.soon":"Tērā ake nei","dl.notify":"🔔 Whakamōhio mai ina tuwhera","dl.notifySmall":"Alpha, beta rānei","hero.secondary":"Agile, engari kāore te rōpū e hiahia ana ki te kawhe tū. (Heoi ka mahi tonu rātou i ngā stand-up.)","pitch.h2":"AI-gile i te maha o ngā kupu e hiahia ana koe","pitch.lede":"Kōwhiria te roa, mai i te kupu kotahi ki te 144. He whakaahuatanga motuhake ia roa, i tuhia mō taua rahi. Toia te kaiwhakahaere, whakamahia rānei ngā pātuhi pere.","pitch.rangeLabel":"Te roa i ngā kupu","pitch.dice":"🎲 tētahi atu putanga","pitch.words.one":"{n} kupu","pitch.words.other":"{n} kupu","pitch.letters.one":"{n} reta","pitch.letters.other":"{n} reta","pitch.chars.one":"{n} tohu","pitch.chars.other":"{n} tohu","count.line.html.one":"E {n} ngā kāri kei te papa i tēnei wā","count.line.html.other":"E {n} ngā kāri kei te papa i tēnei wā","people.humans.html.one":"👥 {n} tangata","people.humans.html.other":"👥 {n} tāngata","people.agents.html.one":"🤖 {n} kaiāwhina AI","people.agents.html.other":"🤖 {n} kaiāwhina AI","people.working.html.one":"⚡ {n} e mahi ana ināianei","people.working.html.other":"⚡ {n} e mahi ana ināianei","pre.title":"AI-gile: he mea e hangaia ana","pre.description":"He mea e hangaia ana i konei: he papa e hanga ai ngā rōpū AI i āu e tono ai, ā, ka ako i a koe i te haere tonu. He pre-alpha kati me ngā hoa i tēnei wā.","pre.h1":"He mea e hangaia ana i konei. 🤫","pre.line":"He papa e hanga ai ngā rōpū AI i āu e tono ai, ā, ka ako i a koe i te haere tonu. He pre-alpha kati me ngā hoa i tēnei wā.","pre.btn":"🔔 Whakamōhio mai ina tuwhera","pre.peek":"Kei muri i te karaehe: te papa tūturu, ora. He pae tae ia kāri.","pre.peekFake":"Kei muri i te karaehe: te āhua o tētahi papa e mahi ana.","pre.night":"🌙 Ko te kaitiaki o te pō te kaiwhakahaere · 😴 e okioki ana te tangata","features.aria":"Āna mahi","f.pile.h":"Te puranga kotahi mōu","f.pile.html":"<b>Māu</b> kei konei ngā mea katoa e tatari ana ki a koe, puta noa i ngā kaupapa katoa: ngā pātai, ngā mea hei whakamātau, ngā mahi mā te tangata anake. Ka mea tō rārangi he aha te mea e whai ake nei, me te roa e pau ai.","f.sleep.h":"Ngā rōpū e mahi ana i a koe e moe ana","f.sleep.p":"He kaihautū me tētahi rōpū kaiwhakahaere AI tō ia kaupapa. Tāpiritia he kōrero ki tētahi kāri, ka oho te rōpū, ka mahi, ka hoatu anō me ngā hikoi e ngāwari ana mā te tangata ngenge.","f.tester.h":"Ka tirotiro tuatahi he kaiwhakamātau AI","f.tester.p":"I mua i te taenga ki a koe, ka whai te kaiwhakamātau i ngā hikoi i runga i tētahi kape o te taupānga, ka whakaatu i tāna i kite ai, me te tānga mata. Tirohia wawe ngā mea i ngata, ka whakaae mā te pāwhiri kotahi.","f.proof.h":"He taunakitanga, ehara i te oati","f.proof.p":"Ka whakaatu ia tuku i ngā mea kua rerekē: ngā kōnae, te rerekētanga, ngā tānga mata. Kāore e tika kia whakatuwheratia ia taupānga hei tiro mēnā kua oti.","f.chat.h":"Kōrero ki ō kaihautū","f.chat.p":"He kōrero-ara pērā i a Discord: kotahi te tohu mō ia kaupapa, he taimana waiporoporo mō ngā mea e hiahia ana ki a koe. Tukuna he whakaaro ki tētahi kaihautū; ka huri ia hei kāri me tētahi mahere, me tētahi pātene ✅ Haere.","f.tidy.h":"Ka noho ia i te tōtika","f.tidy.p":"Ka whakakotahi ngā kāri e hāngai ana, ka whakatikahia ngā taitara rangirua, ā, ka tiaki te tirotiro tohu i te waehere kia kōmaki. Torutoru ake ngā mea hei huri atu ki, torutoru ake ngā mea hei whakaaro.","f.private.h":"Nōu, i runga i tō rorohiko","f.private.li1":"Ka rere te papa i runga i tō ake rorohiko, ā, ko koe anake tāna e whakautu ai.","f.private.li2":"He hunahuna ngā karere tūmataiti i waenga i ngā tāngata, mai i tētahi pito ki tētahi.","f.private.li3":"Kāore he kāute, kāore he kaiwhai, kāore he pihikete.","f.lang.h":"I tō reo","f.lang.p":"Neke atu i te 120 ngā reo, mai i te Tati, te Wēra me te Hapani ki te kaipahua, ki a Yoda me te Klingon, me tētahi whakawhiti tere ki te reo Ingarihi mō ngā kupu ngaio.","f.service.h":"Mai i tētahi whakaaro ki tētahi ratonga tūturu","f.service.p":"Kua hanga koe i tētahi mea me te AI e whakamahia ana e te tangata ināianei? Tohua hei ratonga, ā, ka āwhina te papa i a koe ki te whakahaere pai: ngā arowhai uptime, he whārangi tūnga tūmatanui, ngā aitua me tētahi pūrongo, ngā panonitanga me whai Haere, ngā kape tiaki ka tirotirohia ia rā. Ka ako te Āwhina i ia hipanga i a koe e haere ana.","msgr.h2":"AI-gile Messenger: tō rōpū i tō pūkoro","msgr.p1":"Kōrero ki tō rōpū AI me te kore e whakatuwhera i te papa. Kōrerorero ki ō kaiārahi kaupapa me ō hoa, tirohia ngā hipanga whakamātau o tētahi kāri ka whakautu ai, mai i tō waea katoa.","msgr.p2":"Hei hono, matawaitia tētahi waehere QR i tō papa. Te wā tuatahi? Mā tētahi kōrerorero whakaatu ngāwari koe e ārahi.","msgr.when":"Ko Android tuatahi, kātahi he putanga ipurangi mō ngā waea me te iPhone.","msgr.who":"Tō kaiārahi kaupapa","msgr.b1":"Kua rite te whakatika mō te aratau pōuri. Me tuku atu ngā hipanga whakamātau?","msgr.b2":"Āe rā, tēnā!","msgr.b3":"1. Whakatuwheratia ngā Tautuhinga. 2. Kōwhiria te Pōuri. He tika te āhua?","tl.aria":"Rārangi wā mai i te kōrero tuatahi ki te mahere","tl.h2":"Mai i te kōrero tuatahi ki te mea e haere ake nei","tl.lede":"He rā me ngā wā tūturu, i tō ake rohe wā. Whai muri i tēnei rā he mahere, kāore he rā i oatitia.","tl.today":"Tēnei rā","tl.planned":"kua whakaritea","tl.doing":"e mahi ana","tl.cards.one":"{n} kāri","tl.cards.other":"{n} kāri","join.h2":"Haere mai ki roto","join.lede":"Kei te hangaia a AI-gile e tētahi tangata pāhau rerekē, he AuDHD tōna, he pakanga anō ōna ki te hauora hinengaro, me te tini o ngā kaiwhakahaere manawanui. He tūmataiti i tēnei wā, i te alpha kati me ngā hoa. Kei te hiahia koe ki te whakamātau ina tuwhera?","join.btn":"Tohua tō aro","join.small":"Ka īmēra atu mātou, kāore atu","footer.tag":"AI-gile. Kāore he kaiwhai, kāore he pihikete, kāore he kawhe tū.","footer.licence":"Raihana pakihi","footer.status":"Tūnga","footer.privacy":"Ngā mea ka puritia e mātou","footer.thanks":"Ngā waea, he mihi ki a ChilledChat","form.sending":"E tuku ana…","form.failed":"Kāore i whai hua: whakamātauria anō a muri ake nei.","form.offline":"Kāore i taea te toro atu ki a AI-gile: whakamātauria anō a muri ake nei.","form.keep":"Ka whakamahia tēnei hei whakautu noa i a koe, kātahi ka mukua. Kāore he kaiwhai, kāore he pihikete.","form.keepLink":"Ngā mea ka puritia e mātou","interest.title":"AI-gile: whakamōhiotia mai ina tuwhera te alpha","interest.description":"Waihotia tō īmēra kia mōhio koe ina tuwhera te alpha kati, te beta rānei o AI-gile.","interest.h1":"🔔 Whakamōhio mai ina tuwhera","interest.lede":"Kei te pre-alpha kati a AI-gile. Waihotia tō īmēra, ā, ka tuhi atu mātou kotahi anake, ina whai wāhi koe.","interest.email":"Tō īmēra","interest.which":"Tēhea whakamātautau?","interest.alpha":"Alpha kati: tōmua, taratara, he maha ngā panoni","interest.beta":"Beta: kua pūmau ake, mō muri","interest.both":"Tētahi, ko tēhea te tuatahi","interest.submit":"Tāpiritia ahau ki te rārangi","interest.thanks":"Ngā mihi! Kei te rārangi koe.","licence.title":"AI-gile: raihana pakihi","licence.description":"E whakamahi ana i a AI-gile i tō pakihi? Tonoa he raihana pakihi koreutu.","licence.h1":"📜 Raihana pakihi","licence.lede":"E whakamahi ana i a AI-gile i te mahi? Kōrerotia mai ko wai koe, he aha tāu mahi. Mēnā he painga tāna, he koreutu te raihana.","licence.company":"Kamupene","licence.website":"Pae tukutuku","licence.what":"Tāu mahi","licence.how":"Tōna āwhina ki te ao","licence.email":"Īmēra","licence.submit":"Tono","licence.thanks":"Ngā mihi! Ka whakautu atu mātou mā te īmēra.","status.title":"Tūnga o AI-gile","status.h1":"Tūnga o AI-gile","status.quiet":"Kāore he raruraru","status.intro":"Kei te mahi a AI-gile i tēnei wā? Ka tirotirohia e tēnei whārangi te paetukutuku, te tiri papa, ngā waea me te tikiake ia 5 meneti.","status.up":"Kei te mahi (i whakautu i roto i te {ms} ms)","status.slow":"Kāore i whakautu ki te tirotiro whakamutunga, e whakamātau anō ana","status.down":"Kua hinga: kāore i whakautu ki ngā tirotiro whakamutunga e rua","status.svc.web":"Paetukutuku","status.svc.web.offers":"Tēnei pae: he aha a AI-gile, me te puka tohu aro","status.svc.boards":"Tiri papa","status.svc.boards.offers":"Ngā papa tūmatanui, ngā karere i waenga i ngā hoa, me ngā tono","status.svc.calls":"Ngā waea","status.svc.calls.offers":"Reo, ataata me te tiri mata i roto i a AI-gile","status.svc.download":"Tikiake","status.svc.download.offers":"Te kaitāuta Windows me ngā hono tono","status.checking":"E tirotiro ana…","status.offline":"Kāore e taea te toro ki te ratonga tūnga i tēnei wā (e whakamātau anō ana)","status.updated":"i whakahoutia {ago}","status.justNow":"inaianei tonu","status.min":"{n} meneti ki muri","status.hours":"{n} hāora ki muri","status.days":"{n} rā ki muri","privacy.title":"AI-gile: ngā mea ka puritia e mātou","privacy.h1":"Ngā mea ka puritia e mātou","privacy.lede":"Hei kōrero poto: ko ngā mea anake ka tukuna mai e koe, ā, mō te wā poto noa.","privacy.only":"Ko ngā mea anake ka tukuna mai e koe: ko ngā mea ka patoa e koe ki tētahi puka, pērā i tō īmēra. Kāore he mea kē atu mōu.","privacy.sealed":"Ka hiritia kia kore ai e taea e tō mātou tūmau te pānui: i roto i tō pūtirotiro i mua i tōna wehenga atu (i tētahi pūtirotiro tawhito, i te wā tonu ka tae mai). Ko tō mātou ake papa anake e taea ai te whakatuwhera.","privacy.server":"Ka mukua i te tūmau i te wā tonu ka tae ki tō mātou papa. Ko ngā mea kei reira tonu i muri i te 30 rā, ka mukua ahakoa te aha.","privacy.board":"Ka puritia e mātou ki tō mātou papa kia whakautu rā anō mātou ki a koe, kātahi ka mukua ki reira hoki.","privacy.none":"Kāore he kaiwhai, kāore he pihikete, kāore he tātari raraunga.","privacy.local":"Ko tō reo me tō kōwhiringa mārama, pōuri rānei ka noho tonu ki tō ake pūtirotiro. Kāore rawa e tukuna mai ki a mātou.","privacy.ask":"E hiahia ana kia mukua wawetia? Whakautua tā mātou īmēra, ka kī mai ai.","live.h2":"Matakitaki i tana hanganga, ora","live.caption":"Kua huna ia kāri katoa: ka kite koe i te āhua o te mahi, kaua ko ngā kupu.","live.watching.one":"ora: {n} e matakitaki ana","live.watching.other":"ora: {n} e matakitaki ana","live.last.now":"I nekehia te kāri whakamutunga inaianei tonu","live.last.min.one":"I nekehia te kāri whakamutunga {n} meneti kua pahure","live.last.min.other":"I nekehia te kāri whakamutunga {n} meneti kua pahure","live.last.hour.one":"I nekehia te kāri whakamutunga {n} haora kua pahure","live.last.hour.other":"I nekehia te kāri whakamutunga {n} haora kua pahure","live.last.day.one":"I nekehia te kāri whakamutunga {n} rā kua pahure","live.last.day.other":"I nekehia te kāri whakamutunga {n} rā kua pahure","live.offline":"Kei te okioki paku te papa ora. Hoki mai a muri nei.","live.cols":"Backlog|Hei mahi|E mahi ana|E arotakengia ana e te rōpū|Māu e test|Mā te rōpū|Oti","footer.models":"Ka whakahaerehia e AI-gile ngā tauira AI mōu. Ko ā rātou kōrero me ā rātou mahi he nā rātou, nō reira arohia i mua i tō whakapono.","privacy.ai.h":"Te wāhanga AI","privacy.ai.models":"Ko AI-gile te papa. Mahia ai te mahi e ngā tauira AI nō ngā kamupene ke, pērā i a Claude, Codex me Gemini, ki ō ake pūkete.","privacy.ai.check":"Ko ā rātou tuhi me ā rātou mahi, nō rātou ake, ā, tērā pea he hē. Arohia i mua i tō whakawhirinaki, i tō tuku rānei.","privacy.ai.files":"Ka whakarerekē rātou i ngā kōnae, ka whakahaere hoki i ngā whakahau i ngā kōpaki ka hono atu koe. Mahia he kape tautoko.","privacy.ai.send":"Ko tā koe e hoatu ai ki tētahi tauira ka haere ki te kamupene e whakahaere ana i a ia, i raro i ō rātou here. Ka pā ngā here me ngā utu o ia kamupene.","privacy.ai.asis":"He putanga whakamātau moata a AI-gile, e hoatu ana pēnei i tōna āhua."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Karetao.","Tukuna."]},{"n":2,"texts":["Kanban karetao.","Whakaaro, hangaia.","Mahi tukuna."]},{"n":3,"texts":["Kanban mō karetao.","Whakaaro hei āhuatanga.","Kanban kaiwhakahaere koreutu."]},{"n":5,"texts":["Papa kanban, ngā kaiwhakahaere hanga.","Tuhia ngā kāri. Hangaia e rātou.","Koreutu, ā-rorohiko, kua whakamātauria, āhua porangi."]},{"n":8,"texts":["He papa kanban koreutu e mahi ai ngā kaiwhakahaere AI.","Tuhia he whakaaro. Ka hangaia e ngā kaiwhakahaere. Whakaaetia.","Agile mō te tangata kotahi me te tini karetao manawanui."]},{"n":13,"texts":["He papa kanban i tō rorohiko e tango ai ngā kaiwhakahaere AI i ngā kāri.","Tuhia he whakaaro. Ka hangaia e tētahi rōpū kaiwhakahaere. Ka tirotirohia e tētahi kaiwhakamātau.","Kāore he kāute, kāore he kaiwhai: he papa, he karetao, ā, ko koe te rangatira."]},{"n":21,"texts":["He papa kanban a AI-gile hei mahi tahi ki ngā kaiwhakahaere waehere AI. Ka tango rātou i ngā kāri; mā koe e whakamātau, e whakaae.","He kaihautū me tētahi rōpū kaiwhakahaere AI tō ia kaupapa. Tāpiri kōrero ki tētahi kāri, ka tīmata te rōpū ki te mahi.","He papa mahi tūmataiti, koreutu, e rere ana i tō rorohiko. Ko ngā kaimahi he karetao. Ko koe te kaiwhakaae."]},{"n":34,"texts":["Ka whakatakotoria e koe ngā whakaaro ki te papa. Ka huria e tētahi rōpū kaiwhakahaere AI hei āhuatanga e mahi ana, ka whakamātauria, ka hoatu me ngā hikoi hei whakamātau. Kāore he mea e oti kia kore koe e kī.","He papa kanban i hangaia ā-ringa e Rich, me te āwhina nui a ngā kaiwhakahaere e whakahaerehia ana e ia inaianei. He koreutu, e rere ana i tō rorohiko, ā, ka tukua ki ngā hoa, ehara i te hoko.","Whakaarohia he papa kanban, he pou mai i te Backlog ki te Oti, engari ko ngā kaiwhakahaere AI ngā kaitango i ngā kāri. Ka kōrero rātou mō te ahunga whakamua, ka pātai ina piri, ā, ka tatari ki tō tohu pai."]},{"n":55,"texts":["He papa kanban a AI-gile e mahi ai ngā kaiwhakahaere AI hei rōpū. He kaihautū tō ia kaupapa hei whakamahere i te mahi, me ngā kaiāwhina hei hanga. Ina rite tētahi āhuatanga, ka whakamātauria e te kaiwhakamātau AI, ka tango tānga mata, ā, ka tae ki tō puranga. Whakaaetia, kōrerotia rānei, ā, ka mahi anō rātou.","I tīmata mai hei huarahi mā tētahi tangata ki te aroturuki i te maha o ngā wā mahi waehere AI i te wā kotahi, ā, i tupu hei papa tika. Ka rere i tō rorohiko, kāore he kāute e hiahiatia, kāore he kaiwhai. He koreutu mō ngā hoa me te hunga hihiri. Kāore anō kia oti, ka kitea ētahi tapa taratara me tētahi ohorere.","Anei te putanga pono. Māu tonu e whakaaro ngā whakaaro, māu tonu e tirotiro ngā putanga. Ko te mahi a AI-gile ko ngā mea katoa kei waenganui: ka tiaki i ngā kāri kia tōtika, ka whakaoho i te kaiwhakahaere tika ina kōrero koe, ka whakaatu he aha te mea kua rerekē, ka whakahaere i te katoa ki tētahi puranga poto mōu."]},{"n":89,"texts":["He papa kanban koreutu a AI-gile e rere ana i tō ake rorohiko. Hei utu mō ngā tāngata, he rōpū kaiwhakahaere AI tō ia kaupapa: he kaihautū hei huri i ō whakaaro hei kāri me tētahi mahere, me ngā kaiāwhina hei tango i ngā kāri i te raupapa matua. Ina oti tētahi mea te hanga, ka whai te kaiwhakamātau AI i ngā hikoi whakamātau, ka whakaatu i tāna i kite ai. Kātahi ka tatari ki roto i tētahi puranga e kīia ana Māu. Whakaaetia, kōrerotia rānei, ā, ka whakamātau anō te rōpū. Kāore he mea e tae ki Oti ki te kore koe.","Ētahi āhuatanga kāore pea koe e tūmanako. Ka whakakī te kaitiaki pō i te pou Hei mahi i a koe e moe ana, mā te kōwhiri i ngā kāri kāore e hiahia ana ki tō whakautu. Ka whakaatu te kaiwhakatatau tohu i te nui o tā ngā kaiwhakahaere whakamahi i tēnei rā, i tēnei wiki hoki. Ka taea e koe te tuku karere ki ngā hoa, ā, he hunahuna ngā karere tūmataiti mai i tētahi pito ki tētahi. E kōrero ana te papa i te 120 reo, tae atu ki te Tati, te kaipahua me te Klingon. Kāore tētahi o ēnei e utu moni.","He kaupapa iti, whaiaro a AI-gile, ehara i te kamupene. I hiahia a Rich ki te tiaki i ētahi kaupapa waehere AI me te kore e whakatuwhera i ia taupānga hei tirotiro, nā reira ka hangaia e ia me ngā kaiwhakahaere he papa mō tērā, ā, ka whakamahia taua papa ki te hanga i te toenga o ia ake. Kei te pre-alpha kati, arā, ka mahi, te nuinga o te wā, mō ētahi hoa torutoru. Kāore he whārangi utu, kāore he pānuitanga, kāore he mahere tipu. Mēnā he whai take, ka taea e koe te tono kia whakamātau ina tuwhera whānui ake."]},{"n":144,"texts":["He papa kanban a AI-gile mō tētahi tangata me te tini o ngā kaiwhakahaere AI. Ka rere i tō ake rorohiko, ā, he koreutu rawa. Ka kōrero koe ki te kaihautū, pērā i a Discord, ka whakaahua i tētahi whakaaro; ka huri te kaihautū hei kāri me tētahi mahere, ā, ka tatari kia pēhia e koe te Haere. Ka mahi te rōpū i ngā kāri i te raupapa matua, mā tētahi rārangi whakahau ngāwari i hangaia mō ngā tauira reo. I mua i te hokinga mai ki a koe, ka whai te kaiwhakamātau AI i ngā hikoi i runga i tētahi kape o te taupānga, ka tāpiri i tētahi tānga mata. Ka tae te mahi kua oti ki tō puranga me ngā kōnae kua rerekē me te rerekētanga. Ka whakaae koe, ka waiho rānei he kōrero, ā, ka oho te rōpū, ka whakamātau anō. Ko koe anake e taea te nuku i tētahi kāri ki Oti.","Anei te āhua o tētahi rā me AI-gile. I te ahiahi ka waiho e koe ētahi kōrero: kei te wāhi hē tēnei pātene, me whakarōpū tērā rārangi, me whai aratau pōuri pea. Ka haere koe ki te moe. Ka pānui ngā kaiwhakahaere i ngā kōrero, ka whakarerekē, ka whakamātau, ka hoatu anō ki a koe. Mēnā ka maroke te Hei mahi, ka whakakī te kaitiaki pō i a ia mai i te backlog ki ngā kāri kāore e hiahia ana ki tō whakautu. I te ata he puranga poto kotahi: tētahi rua pātai me ētahi mea hei whakamātau, tēnā me tēnā me ngā hikoi e taea e te tangata ngenge, me tētahi tānga mata e whakaatu ana kei te mahi. Ka pāwhiri koe, ka whakaae i ngā mea pai, ka whakahoki i te toenga. Ka whakaatu te kaiwhakatatau tohu i te nui o te pau, ā, kei reira te Aratau Kore Tohu mō ngā wiki kōmaki. Kātahi koe ka kai parakuihi, kāore anō kia taea e ngā kaiwhakahaere te āwhina.","Tuatahi, ehara a AI-gile i te aha. Ehara i te kamupene hōu, ehara i te mea e hokona ana, ā, kāore he tangata e kohi ana i ō raraunga. He papa koreutu e rere ana i tō rorohiko, kāore he kāute, kāore he kaiwhai, kāore he pihikete. Ko te mea ia: kotahi te wāhi tōtika hei tiro i ngā kaupapa waehere AI katoa i te wā kotahi, ko tētahi rōpū kaiwhakahaere e mahi ana i ngā kāri, ā, māu ngā whakatau. E kōrero ana i te 120 reo, mai i te Tati ki te kaipahua me te Klingon. I hangaia e Rich me te tini o ngā kaiwhakahaere manawanui, te nuinga mā te whakamahi i a ia ake. Kei te pre-alpha kati, nō reira he taratara ētahi wāhi. Mēnā he hākinakina, pātai atu i runga i te mihi, ā, tērā pea ka uru wawe koe."]}],"quips":{"1":"Kotahi te kupu. Pakari. Tērā pea he nui rawa te pakari.","3":"E toru ngā kupu. Kua pono ake i te nuinga o ngā whārangi hua.","8":"E waru ngā kupu. He poto tonu i tētahi stand-up.","21":"He tohu kōrero ngā roa, nā. Ae rā.","55":"E rima tekau mā rima ngā kupu. E rua ngā kāri i oti i a koe e pānui ana.","144":"Koinei te mea roa. Kāore he 233. Kua haere ngā kaiwhakahaere ki te moe."}},"timeline":{"first-idea.name":"Te whakaaro tuatahi","first-idea.line":"Te kōrero tuatahi rawa, i mua i te whai waehere.","first-board.name":"Te papa tuatahi","first-board.line":"He papa e whai ana i tōna ake hanga: ngā kāri, ngā pou, te toia, ngā kaupapa.","team-roles.name":"Te rōpū me ngā tūranga","team-roles.line":"Ngā kōtaha kaiwhakahaere, ngā tauira rōpū, ngā mokowā me te mahi a ia tangata.","install.name":"Te tāuta me ngā tukunga","install.line":"He zip e taea e tētahi hoa te tāuta, te whakahou-ā-tinana, ngā hongere me te hoki whakamuri.","usage-saver.name":"Te kaitiaki whakamahinga","usage-saver.line":"Ine i te utu o ngā whakahaerenga, kia kōmaki te waehere, kia mau tō tepe.","friends.name":"Ngā hoa me te tiritiri","friends.line":"Ngā karere tūmataiti, he hononga hunahuna, ngā pōwhiri, ngā tūranga me ngā kaupapa tiritahi.","languages.name":"Ngā reo","languages.line":"Ia kupu o ia mata i tētahi kōnae reo, ko te Tati tuatahi.","ai-tester.name":"Kaiwhakamātau AI","ai-tester.line":"Ka tirotiro tuatahi tētahi kaiwhakamātau i ia tukunga, ka whakaatu i tāna i kite ai.","website.name":"Te pae tukutuku","website.line":"aigile.lol, te whārangi tīmatanga me tēnei rārangi wā.","streaming.name":"Te kōrero me te rere ora","streaming.line":"Discord, Twitch, OBS, te aratau kaiwhakaatu, ngā GIF me ngā emoji.","no-ai.name":"Te putanga kore AI","no-ai.line":"He papa mō te hunga e waehere ana me te kore AI, me ngā papa tūmatanui.","night-watch.name":"Te kaitiaki pō","night-watch.line":"Ka whakahaere tētahi kaitiaki me tētahi Scrum Master i ngā rōpū i a koe e moe ana.","p-more.name":"Ngā mea katoa atu","p-more.line":"Ngā whakaaro iti e tatari tonu ana i tō rātou wā.","p-android.name":"Te waea me Android","p-android.line":"Toro atu ki tō papa mai i te waea, kātahi he taupānga Android ake.","p-release.name":"Te alpha me tua atu","p-release.line":"Te alpha kati, te pae ora, kātahi te beta.","p-languages.name":"Ētahi atu reo","p-languages.line":"130 ngā reo, me tētahi aratau rumaki mō ngā ākonga.","p-engines.name":"Ētahi atu pūkaha AI","p-engines.line":"Kōwhiria a Claude, Codex, Gemini, Copilot, Cursor rānei mō ia kaiwhakahaere.","p-pro.name":"Te tikanga ngaio","p-pro.line":"Ngā tūtohu tūpono, ngā kēti whakakotahi, ngā kāri aituā me ngā tiaki.","p-self.name":"Te tiaki i a koe","p-self.line":"Te aratau ngenge, ngā whakamahara tiaki-whaiaro me te 4:20.","p-servers.name":"Ngā tūmau me te whānui","p-servers.line":"Ngā tautuhinga tūmau ao, ngā tūranga me te whakamahere mō te tipu.","p-livestream.name":"Ngā taapiri rere ora","p-livestream.line":"Te kōrero Twitch, ngā emoji ake me tētahi tirohanga ora tūmatanui."},"words":{"button":"📖 Ngā kupu ngaio","h":"📖 Ngā kupu kua whakamāramatia","intro":"Te whakangungu koreutu i te reo māmā: ngā kupu katoa ka tūtaki ai koe, mai i te whakaaro tuatahi tae noa ki te ratonga e whirinaki ai te tangata, me Agile, te hanga, te pupuri haumaru me te mahi tahi me te AI i te haerenga.","search":"Rapua he kupu…","none":"Kāore he kupu e hāngai ana.","close":"Katia","count":{"one":"{count} kupu","other":"{count} kupu"},"groups":[{"id":"idea","name":"💡 Whakaaro me te rapu"},{"id":"plan","name":"🗺️ Te whakamahere i te mahi"},{"id":"agile","name":"🔁 Ngā tikanga mahi Agile"},{"id":"build","name":"🛠️ Te hanga"},{"id":"test","name":"🧪 Te whakamātau me te kounga"},{"id":"change","name":"🔀 Te panoni haumaru"},{"id":"run","name":"🛎️ Te whakahaere ratonga"},{"id":"sec","name":"🔒 Te haumaru me te noho muna"},{"id":"ai","name":"🤖 Te mahi tahi me te AI"},{"id":"money","name":"💰 Te moni me ngā raihana"}],"list":[{"id":"discovery","g":"idea","word":"Te rapu (Discovery)","text":"Te wāhanga tuatahi o te rapu he aha te raru e whai take ana kia whakaotia, mō wai hoki, i mua i te hanga i tētahi mea.","also":["wāhanga rapu","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Tauākī raru (Problem statement)","text":"Kotahi, e rua rānei ngā rerenga kōrero e kī ana ko wai kei a ia te raru, he aha taua raru, he aha hoki te take nui, kia kotahi ai te whāinga a te katoa.","also":["tauākī raru","problem statements"]},{"id":"user","g":"idea","word":"Kaiwhakamahi (User)","text":"Te tangata e whakamahi ana i tā koe e hanga ana. Ko ōna hiahia te take o te mahi.","also":["kaiwhakamahi","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Te hunga whai pānga (Stakeholder)","text":"Ia tangata e aro ana ki te putanga o te mahi, e pāngia ana rānei e taua mahi, pēnei i te hunga e utu ana, e whakamahi ana, e tautoko ana rānei.","also":["te hunga whai pānga","stakeholders"]},{"id":"persona","g":"idea","word":"Tangata whakatauira (Persona)","text":"He tangata pohewa, engari he āhua tūturu, hei māngai mō tētahi momo kaiwhakamahi, kia pātai ai te rōpū, “Ka māmā tēnei ki a Hēmi?”","also":["tangata whakatauira","personas"]},{"id":"userresearch","g":"idea","word":"Rangahau kaiwhakamahi (User research)","text":"Te kōrero ki ngā tāngata tūturu me te mātakitaki i a rātou, kia mōhio ai he aha ā rātou hiahia, kaua e whakapae noa.","also":["rangahau kaiwhakamahi","user interviews","uiui kaiwhakamahi"]},{"id":"journey","g":"idea","word":"Haerenga kaiwhakamahi (User journey)","text":"Ngā takahanga e whakatutuki ai te tangata i tētahi mahi, mai i tana rongo tuatahi tae noa ki te otinga, tae atu ki waho i tāu hua. Mā te tuhi i tēnei ka kitea ngā wāhi e raru ai rātou.","also":["haerenga kaiwhakamahi","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Wāhi mamae (Pain point)","text":"Tētahi mea e whakahōhā ana, e whakapōturi ana rānei i te tangata i tēnei wā. Ka whakakorea e ngā hua pai ngā wāhi mamae.","also":["wāhi mamae","pain points"]},{"id":"assumption","g":"idea","word":"Whakapae (Assumption)","text":"Tētahi mea e whakapono ana koe engari kāore anō kia tirohia. Mā te tuhi i ngā whakapae ka kitea he aha hei whakamātau i te tuatahi.","also":["whakapae","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Whakapae whakamātau (Hypothesis)","text":"He matapae pai rawa e whakamahere ana koe ki te tirotiro, me te mea e tūmanako ana koe ka puta, pēnei i “ka haina mai te tangata mēnā he utu kore te marama tuatahi”.","also":["whakapae whakamātau","hypotheses"]},{"id":"experiment","g":"idea","word":"Whakamātau (Experiment)","text":"He whakamātau iti kua whakaritea hei mōhio mēnā e whai hua ana tētahi whakaaro, i mua i te whakapau nui ki runga.","also":["whakamātau","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Whakaaturanga ariā (Proof of concept, PoC)","text":"He whakamātau tere, taratara hei kite mēnā ka taea rawa tētahi whakaaro. I te nuinga o te wā ka makaia atu ina whiwhi koe i te whakautu.","also":["PoC","proof of concept","whakaaturanga ariā"]},{"id":"prototype","g":"idea","word":"Tauira tuatahi (Prototype)","text":"He tauira moata o te hua, he pikitia ka taea te pātō i te nuinga o te wā, hei whakamātau i te whakaaro ki ngā tāngata i mua i te hanga tika.","also":["tauira tuatahi","prototypes"]},{"id":"wireframe","g":"idea","word":"Anga mata (Wireframe)","text":"He huahua māmā o tētahi mata e whakaatu ana i te wāhi mō ia mea, kāore he tae, kāore he ihirangi tūturu.","also":["anga mata","wireframes"]},{"id":"mockup","g":"idea","word":"Tauira tirohanga (Mockup)","text":"He pikitia taipitopito e whakaatu ana i te āhua o tētahi mata, me ōna tae me ōna kupu tūturu, engari kāore anō tētahi mea kia mahi.","also":["tauira tirohanga","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Take pakihi (Business case)","text":"Ngā take hei whakatutuki i tētahi kaupapa: te utu, ngā hua ka puta mai, ngā moni ka penapenatia rānei, me ngā tūraru.","also":["take pakihi","business cases"]},{"id":"feasibility","g":"idea","word":"Te taea (Feasibility)","text":"Mēnā ka taea tūturu te hanga me te tiaki i tētahi mea i runga i te wā, te moni me ngā pūkenga kei a koe.","also":["te taea"]},{"id":"outcome","g":"idea","word":"Putanga hua (Outcome)","text":"Te rerekētanga e hiahia ana koe mō ngā tāngata, pēnei i te iti ake o ngā hui kua hapa. He nui ake tōna hira i te nui o tā koe i hanga ai.","also":["putanga hua","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Hua mahi (Output)","text":"Tētahi mea ka hangaia e te rōpū, pēnei i tētahi mata hou, i tētahi pūrongo rānei. Ahakoa kua hangaia, ehara i te mea kua āwhina i tētahi.","also":["hua mahi","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Inenga angitu (Success metric)","text":"He tau e whakaatu ana mēnā i whakatutuki te mahi i tōna take, pēnei i te nui ake o te hunga e whakaoti ana i tā rātou ota.","also":["inenga angitu","success metrics"]},{"id":"kpi","g":"idea","word":"Tohu tutukinga matua (KPI)","text":"He tau hira e mātakitaki ana koe hei kite mēnā e pai ana te haere, pēnei i te maha o ngā hainga ia wiki.","also":["KPI","KPIs","key performance indicator","tohu tutukinga matua"]},{"id":"okr","g":"idea","word":"Ngā whāinga me ngā hua matua (OKR)","text":"He tikanga whakarite whāinga: ka kī te whāinga he aha tāu e hiahia ana, ā, ko ētahi hua matua he tau hei whakaatu kua tae koe.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Hua (Product)","text":"Te mea e hangaia ana, e tiakina ana mō ōna kaiwhakamahi, pēnei i tētahi taupānga, i tētahi pae tukutuku, i tētahi taputapu rānei.","also":["hua","products"],"noTip":1},{"id":"vision","g":"plan","word":"Tirohanga whakamua o te hua (Product vision)","text":"He tauākī poto mō ko wai e āwhinatia ana e te hua me tōna ahunga whakamua mō te wā roa.","also":["tirohanga whakamua o te hua","vision statement"]},{"id":"po","g":"plan","word":"Kaipupuri hua (Product owner, PO)","text":"Te tangata ka whakatau he aha te mea ka hangaia, ā, i tēhea raupapa, kia mahi tonu te rōpū i te mea nui rawa. I roto i a AI-gile, ko koe tērā.","also":["PO","product owners","kaipupuri hua"]},{"id":"pm","g":"plan","word":"Kaiwhakahaere hua (Product manager, PM)","text":"Te tangata e tiaki ana i te ahunga o tētahi hua: ko ēhea raru e whakatauria ana, mō wai, he aha hoki. Ka tikanga hoki te PM ko te kaiwhakahaere kaupapa, nō reira tirohia.","also":["kaiwhakahaere hua","product managers"]},{"id":"projmgr","g":"plan","word":"Kaiwhakahaere kaupapa (Project manager)","text":"Te tangata e pupuri ana i te kaupapa kia tika te wā me te tahua, e aroturuki ana ko wai e mahi ana i te aha, ā, hei āhea.","also":["kaiwhakahaere kaupapa","project managers"]},{"id":"roadmap","g":"plan","word":"Mahere ara (Roadmap)","text":"He mahere whānui mō ngā mea e haere mai ana i ngā marama e heke mai nei, i runga i te raupapa. E whakaatu ana i te ahunga, ehara i ngā rā tōtika, ā, ka rerekē i a koe e ako ana.","also":["mahere ara","roadmaps"]},{"id":"milestone","g":"plan","word":"Tohu whakatutuki (Milestone)","text":"He wāhi i roto i te kaupapa e tika ana kia tohua, pēnei i “kua whakaputaina te putanga tuatahi”, i “kotahi rau ngā kaiwhakamahi” rānei.","also":["tohu whakatutuki","milestones"]},{"id":"mvp","g":"plan","word":"Hua iti rawa e whai hua ana (Minimum viable product, MVP)","text":"Te putanga iti rawa o tētahi hua e whai hua tonu ana mō ngā tāngata tūturu, kia ako ai koe i a rātou i te wā moata.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Hiahiatanga (Requirement)","text":"Tētahi mea me mahi, me whai rānei te hua kua oti.","also":["hiahiatanga","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Whānuitanga (Scope)","text":"Ngā mea kei roto i te mahi, ā, he ōrite te hira, ngā mea kāore i roto.","also":["whānuitanga","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Te tupu haere o te whānuitanga (Scope creep)","text":"Ina tāpiritia haeretia ētahi mea anō ki te mahi, paku noa iho ia wā, kāore he tangata i whakaae ki te wā, ki te utu tāpiri rānei, nō reira kāore e tino oti.","also":["te tupu haere o te whānuitanga","feature creep"]},{"id":"feature","g":"plan","word":"Āhuatanga (Feature)","text":"Tētahi mea ka taea e te hua te mahi mō ngā tāngata, pēnei i “tautuhi anō i tō kupuhipa”.","also":["āhuatanga","features"],"noTip":1},{"id":"epic","g":"plan","word":"Mahi nui (Epic)","text":"He mahi nui, rahi rawa kia oti i te kotahi haere, nō reira ka wehea ki ngā kāri iti ake.","also":["mahi nui","epics"]},{"id":"story","g":"plan","word":"Kōrero kaiwhakamahi (User story)","text":"He wāhanga mahi iti i tuhia mai i te taha o te kaiwhakamahi: “Hei kaihoko, e hiahia ana ahau ki te penapena i taku kete, kia whakaoti ai ahau ā muri ake.” Ko te tīmatanga tēnei o te kōrero mō te mea hei hanga.","also":["kōrero kaiwhakamahi","user stories"]},{"id":"ac","g":"plan","word":"Paearu whakaae (Acceptance criteria, AC)","text":"Ngā tirotiro me tutuki i tētahi kāri kia kīia kua oti, i whakaaetia i mua i te tīmatanga o te mahi, pēnei i “kei reira tonu te kete i muri i te takiuru ki waho, ki roto anō”.","also":["paearu whakaae","acceptance criteria"]},{"id":"task","g":"plan","word":"Mahi (Task)","text":"Kotahi te mahi hei whakaoti, he takahanga iti o tētahi kōrero kaiwhakamahi nui ake i te nuinga o te wā.","also":["mahi","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tīkiti (Ticket)","text":"Tētahi atu kupu mō te kāri: kotahi te wāhanga mahi, kotahi te tono rānei, e aroturukitia ana mai i te tīmatanga ki te mutunga.","also":["tīkiti","tickets"]},{"id":"priority","g":"plan","word":"Whakaarotau (Priority)","text":"Te hira, te hohoro rānei o tētahi mea ina whakatauritea ki ērā atu, kia mahia tuatahitia ai te mahi nui rawa.","also":["whakaarotau","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Te whakaarotau (Prioritisation)","text":"Te whakarite i te mahi i runga i te raupapa hira. Ko tētahi tikanga rongonui ko MoSCoW: Me whai (Must), Me whai pea (Should), Ka taea te whai (Could), Kāore i tēnei wā (Won’t).","also":["whakaarotau","MoSCoW"]},{"id":"estimate","g":"plan","word":"Whakatau tata (Estimate)","text":"He matapae pai rawa mō te rahi, te roa rānei o tētahi mahi. He matapae, ehara i te kupu oati.","also":["whakatau tata","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Tohu kōrero (Story points)","text":"He tikanga whakatau i te rahi o te mahi mā te whakataurite i ngā kāri ki a rātou anō (“tata ki te rua whakarea te rahi i tērā”), kaua mā ngā hāora. Ehara ēnei i te mea hei whakataurite i ngā rōpū.","also":["tohu kōrero","story point"]},{"id":"tshirt","g":"plan","word":"Te inenga tī-hāte (T-shirt sizing)","text":"Te whakatau i te rahi o te mahi hei S, M, L, XL rānei. He tere, ā, he rawaka mō te whakamahere moata.","also":["rahi tī-hāte","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Poka whakamahere (Planning poker)","text":"He kēmu mō te whakatau tata: ka whakaatu te katoa i tētahi kāri rahi i te wā kotahi, kātahi ka whakamārama te hunga i tohu i te rahi nui rawa me te iti rawa i te take.","also":["poka whakamahere","Scrum poker"]},{"id":"dependency","g":"plan","word":"Te whakawhirinaki (Dependency)","text":"Ina kore e taea tētahi mahi te tīmata, te whakaoti rānei, kia tīmata, kia oti rānei rā anō tētahi atu.","also":["te whakawhirinaki","dependencies"]},{"id":"blocker","g":"plan","word":"Tauārai (Blocker)","text":"Tētahi mea e aukati ana i te mahi i te neke whakamua i tēnei wā, pēnei i tētahi whakautu kāore anō kia tae, i tētahi taputapu pakaru rānei.","also":["tauārai","blockers"]},{"id":"deadline","g":"plan","word":"Rā whakamutunga (Deadline)","text":"Te rā me oti tētahi mea.","also":["rā whakamutunga","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Hua tuku (Deliverable)","text":"Tētahi mea tūturu ka puta mai i te mahi ka tukuna atu, pēnei i tētahi whārangi e mahi ana, i tētahi pūrongo rānei.","also":["hua tuku","deliverables"]},{"id":"forecast","g":"plan","word":"Matapae (Forecast)","text":"He matapae mō te mea ka puta pea, pēnei i te wā ka oti te mahi, i runga i tāu e mōhio ana tae noa ki nāianei.","also":["matapae","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Inenga (Metric)","text":"Tētahi mea e inea ana, e aroturukitia ana i te roanga o te wā, pēnei i te maha o ngā toro ki tētahi whārangi, i te roa rānei o te whakatika.","also":["inenga","metrics"]},{"id":"feedback","g":"plan","word":"Urupare (Feedback)","text":"Ngā kōrero a te tangata ki a koe mō tāu mahi, te pai me te kino. Ko te whiwhi i ēnei i te wā moata, i ngā wā maha hoki, te iho o Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Te rārangi tatari o ngā whakaaro me ngā mahi kāore anō kia whakaritea, kei runga te mea nui rawa. Kāore he mea o reira e mahia kia neke rā anō ki Hei mahi."},{"id":"sprint","g":"agile","word":"Sprint","text":"He wā poto, kua whakaritea, o te mahi (te nuinga he wiki, e rua wiki rānei, kāore e neke atu i te marama kotahi), he whāinga tōna, he huinga kāri kua whakaaetia hei whakaoti.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"He whakapā tere ia rā: he aha te mahi a ia mema o te rōpū, he aha tāna ka mahi ai, he aha hoki te mea e aukati ana i a ia. I Scrum e kīia ana he daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","hui tū ia rā"]},{"id":"kanban","g":"agile","word":"Kanban","text":"He tikanga mahi e neke ana ngā kāri whakawhiti i ngā pou o te papa (pēnei i Hei mahi, E mahi ana, Oti), ā, ka tepe te rōpū i te nui o te mahi e haere ana i te wā kotahi, kia rere tonu ai te mahi."},{"id":"wip","g":"agile","word":"WIP limit","text":"Ko WIP te kupu poto mō work in progress (mahi e haere ana). Ko te tepe WIP te maha o ngā kāri e tika ana kia mau i tētahi pou i te wā kotahi, kia whakaoti ai te rōpū i ngā mea i mua i te tīmata i ētahi atu.","also":["WIP"]},{"id":"dod","g":"agile","word":"Whakamārama o Oti","text":"Te rārangi-tirotiro poto a te rōpū mō te tikanga o “oti”, pēnei i te whakamātautia me te whakamāramatia, i mua i te tukunga o tētahi kāri ki a koe. Ko tōna māhanga, te Whakamārama o Rite, e kī ana āhea e mārama ai te kāri kia tīmata.","also":["Definition of Ready","DoD","DoR","whakamārama o te oti"]},{"id":"retro","g":"agile","word":"Retro","text":"He tiro whakamuri auau ki te āhua o te mahi a te rōpū, kia whakaae ai ki tētahi mea, e rua rānei hei whakapai ake ā muri ake. Te kupu poto mō retrospective. I AI-gile ka whakatakoto te retro i tētahi rerekētanga ki ngā tikanga mahi a te rōpū, ā, ka kī koe “Haere”, “Kāore anō” rānei.","also":["arotake whakamuri","retros","retrospective"]},{"id":"swarm","g":"agile","word":"Kāhui","text":"Mahi tahi katoa: he maha ngā tāngata ka whakarere i ētahi atu mahi hei whakatika tahi i tētahi take ohorere kia oti rā anō. I AI-gile ka āwhina ia rōpū i tētahi kaupapa kotahi, ā, ka tatari ētahi atu kaupapa i tērā wā.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"I Scrum, ko te tangata e āwhina ana i te rōpū kia mahi pai: ka whakakore i ngā aukati, ka pupuri i ngā hui ki te ara, ka whakaako i ngā tikanga pai, me te kore e whakahau taikaha i tētahi. I AI-gile ka kite te Lead Scrum Master i ngā kāri kua mau, ka akiaki i ngā rōpū, ka whakamahara hoki i a koe ki ngā mea e tatari ana, puta noa i ia kaupapa.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (kakama)","text":"He tikanga mahi i ngā takahanga iti: hanga paku, whakaatu hua pono i ngā wā maha, ako i ngā kōrero a te tangata, whakarerekē hoki i te mahere i a koe e haere ana, kaua e whakamahere i ngā mea katoa i te tīmatanga.","also":["Agile development","agile ways of working","whakawhanake Agile"]},{"id":"manifesto","g":"agile","word":"Tauākī Agile (Agile Manifesto)","text":"He tauākī poto i tuhia i te tau 2001 e ngā kaihanga pūmanawa. Ka whakanuia ake e ia ngā tāngata, ngā hua e mahi ana, te mahi tata ki ngā kiritaki me te urupare ki te panonitanga, i ngā mahere taumaha me ngā pepa maha.","also":["Manifesto for Agile Software Development","tauākī Agile"]},{"id":"waterfall","g":"agile","word":"Waterfall (rere wai)","text":"Te tikanga mahi tawhito: whakamahere i ngā mea katoa, kātahi ka hanga katoa, kātahi ka whakamātau katoa, tētahi wāhanga i muri i tētahi. He uaua, he utu nui hoki ngā rerekētanga i te wā tōmuri.","also":["waterfall model","tauira waterfall"]},{"id":"iteration","g":"agile","word":"Hurihanga (Iteration)","text":"Kotahi te hurihanga o te hanga i tētahi mea, te tirotiro, me te whakapai ake. He raupapa o ēnei te mahi Agile, ā, he momo hurihanga te sprint.","also":["hurihanga","iterations"]},{"id":"increment","g":"agile","word":"Tāpiritanga (Increment)","text":"He wāhanga hou e mahi ana ka tāpiritia ki te hua i roto i tētahi sprint, i tētahi hurihanga mahi rānei, ā, e hāngai ana ki ngā mea kei reira kē.","also":["tāpiritanga","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"He tikanga mahi Agile rongonui: ka mahi tētahi rōpū iti i roto i ngā sprint poto ki tētahi whāinga, me ngā tūranga kua whakaritea me ētahi hui auau mō te whakamahere, te tirotiro me te whakapai ake."},{"id":"scrumteam","g":"agile","word":"Rōpū Scrum (Scrum team)","text":"Te rōpū iti e mahi ana i Scrum: he kaipupuri hua, he Scrum Master me ngā kaiwhakawhanake.","also":["rōpū Scrum","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Ngā hui Scrum (Scrum events)","text":"Ngā hui auau i Scrum: te whakamahere sprint, te Scrum ia rā, te arotake sprint me te retro. He tokomaha e kī ana he huihuinga (ceremonies) ēnei.","also":["ceremonies","Scrum ceremonies","ngā huihuinga Scrum"]},{"id":"sprintplan","g":"agile","word":"Te whakamahere sprint (Sprint planning)","text":"Te hui i te tīmatanga o tētahi sprint e whakaae ai te rōpū he aha te hira o te sprint, ko ēhea kāri hei tango, me pēhea te tīmata.","also":["te whakamahere sprint","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Whāinga sprint (Sprint goal)","text":"Kotahi te rerenga kōrero e kī ana he aha te take o te sprint. Ka taea te whakarerekē i ngā mahi iti i te haerenga, kia tutuki tonu te whāinga.","also":["whāinga sprint","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Rārangi mahi sprint (Sprint backlog)","text":"Ngā kāri kua tīpakohia mō te sprint o nāianei, me te mahere a te rōpū hei mahi i ērā.","also":["rārangi mahi sprint","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Rārangi mahi hua (Product backlog)","text":"Te rārangi katoa kua whakaraupapatia o ngā mea ka hangaia pea mō te hua, kei runga te mea nui rawa. Ka rerekē tonu i a koe e ako ana.","also":["rārangi mahi hua","product backlogs"]},{"id":"productgoal","g":"agile","word":"Whāinga hua (Product goal)","text":"Te putanga nui ake e whāia ana e te hua, hei āwhina i te rōpū ki te kōwhiri i te mahi ka whai ake.","also":["whāinga hua","product goals"]},{"id":"refinement","g":"agile","word":"Te whakapai i te rārangi mahi (Backlog refinement)","text":"Te haere auau i te rārangi mahi hei whakanahanaha, wāwāhi, whakaraupapa me te tāpiri taipitopito ki ngā kāri, kia rite ai hei tango. E kīia ana hoki he backlog grooming.","also":["te whakapai i te rārangi mahi","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Te arotake sprint (Sprint review)","text":"He hui i te mutunga o te sprint e whakaatu ai te rōpū i āna mahi kua oti, ā, e whakarongo ai ki ngā whakaaro o te tangata, hei whakatau i te mea ka whai ake.","also":["te arotake sprint","sprint reviews"]},{"id":"demo","g":"agile","word":"Whakaaturanga (Demo)","text":"Te whakaatu i te mahi kua oti e mahi ana, ā-ora, ki te hunga i tono.","also":["whakaaturanga","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Pouaka wā (Timebox)","text":"He wā kua whakaritea mō tētahi mea. Ka pau te wā, ka mutu koe, ahakoa kāore anō kia oti katoa.","also":["pouaka wā","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Tere o te rōpū (Velocity)","text":"Te nui o te mahi e oti ana i te rōpū i ia sprint, e whakamahia ana hei whakamahere i te nui hei tango ā muri ake. Ehara i te kaute mō te pukumahi o te tangata.","also":["tere o te rōpū","team velocity"]},{"id":"capacity","g":"agile","word":"Te āheinga (Capacity)","text":"Te nui o te mahi ka taea e te rōpū te tango i tētahi wā, i muri i ngā hararei me ētahi atu mahi.","noTip":1},{"id":"burndown","g":"agile","word":"Kauwhata heke mahi (Burndown chart)","text":"He kauwhata o te mahi e toe ana i te sprint e heke ana ia rā. Mēnā e papatahi tonu ana te rārangi, kua mau tētahi mea.","also":["kauwhata heke mahi","burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Kauwhata piki mahi (Burnup chart)","text":"He kauwhata o te mahi kua oti e piki ana i te roanga o te wā, i te taha o te tapeke i whakamaheretia, kia kitea ai āhea koe tae ai ki reira.","also":["kauwhata piki mahi","burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Papa Kanban (Kanban board)","text":"Ko te papa ake: he pou mō ia takahanga o te mahi, ā, ka neke whakawhiti ngā kāri.","also":["papa Kanban","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pūnaha kukume (Pull system)","text":"He tikanga mahi e tīmata ai te mahi hou ina he wāhi ki tētahi hei tango, kaua e pēhia ki runga ki tētahi kua kī kē.","also":["pūnaha kukume","pull-based"]},{"id":"flow","g":"agile","word":"Rere (Flow)","text":"Te maeneene o te neke o te mahi i te papa. Ko te tikanga o te rere pai, ka neke tonu ngā kāri, kaua e kōpuni.","also":["te rere o te mahi","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Wā ārahi (Lead time)","text":"Te roa mai i te tono a tētahi tae noa ki te otinga.","also":["wā ārahi","lead times"]},{"id":"cycletime","g":"agile","word":"Wā huringa (Cycle time)","text":"Te roa o tētahi kāri mai i te tīmatanga pono o te mahi ki taua kāri tae noa ki te otinga.","also":["wā huringa","cycle times"]},{"id":"throughput","g":"agile","word":"Hua oti (Throughput)","text":"Te maha o ngā kāri e oti ana i te wiki, i tētahi wā kua whakaritea rānei.","also":["hua oti","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Kakī pounamu (Bottleneck)","text":"Te takahanga kotahi e kōpuni ai te mahi, ā, ka whakaroa i ngā mea katoa i muri, pēnei i te kakī whāiti o te pounamu.","also":["kakī pounamu","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Ara kaukau (Swimlane)","text":"He rārangi whakawhiti i te papa e kohikohi ana i ngā kāri o te momo kotahi, pēnei i te mahi ohorere, i ngā kāri a tētahi rōpū rānei.","also":["ara kaukau","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"He tikanga mahi e tapahi ana i te moumou (ngā mea katoa kāore e āwhina i te kiritaki), ā, e pupuri ana i te rere o te mahi."},{"id":"waste","g":"agile","word":"Moumou (Waste)","text":"I Lean, ko ngā mea katoa e pau ai te kaha engari kāore e āwhina i te kiritaki, pēnei i te tatari, te mahi anō, te hanga rānei i ngā mea kāore he tangata e whakamahi.","noTip":1},{"id":"kaizen","g":"agile","word":"Whakapai ake tonu (Continuous improvement)","text":"Te whakapai paku haere i ngā wā katoa mā ngā rerekētanga iti auau, kātahi ka tirotiro mēnā i whai hua. Ko te retro tētahi huarahi. E kīia ana hoki he kaizen.","also":["whakapai ake tonu","kaizen"]},{"id":"selforg","g":"agile","word":"Rōpū whakahaere i a ia anō (Self-organising team)","text":"He rōpū ka whakatau mā tōna anō me pēhea te mahi, kaua e kīia atu ia takahanga.","also":["rōpū whakahaere i a ia anō","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Rōpū whakawhiti pūkenga (Cross-functional team)","text":"He rōpū kei a ia ngā pūkenga katoa e hiahiatia ana hei whakaoti i te mahi mā tōna anō, pēnei i te hoahoa, te hanga me te whakamātau.","also":["rōpū whakawhiti pūkenga","cross-functional"]},{"id":"spike","g":"agile","word":"Rangahau poto (Spike)","text":"He rangahau poto, he pouaka wā tōna, hei whakautu i tētahi pātai i mua i te whakaū ki te mahi tūturu.","also":["rangahau poto","spikes"]},{"id":"rework","g":"agile","word":"Mahi anō (Rework)","text":"Te mahi anō i te mahi nā te mea kāore i tika i te tuatahi.","also":["mahi anō","reworked"]},{"id":"safe","g":"agile","word":"Agile whānui (SAFe)","text":"Ngā tikanga hei whakamahi i a Agile puta noa i ngā rōpū maha i tētahi whakahaere nui. Ko SAFe (Scaled Agile Framework) tētahi tauira rongonui.","also":["scaled Agile","Agile whānui"]},{"id":"repo","g":"build","word":"Repo","text":"Te kōpaki waehere o te kaupapa me tōna hītori commit katoa. Ka noho pea ki tō rorohiko, ki GitHub, ki ngā mea e rua rānei.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"He rārangi mahi motuhake i te waehere, kia taea ai ngā panonitanga me te kore e pā ki te putanga matua.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"He hopu kua tiakina o te waehere, me tētahi tuhipoka poto mō te mea i panoni. Ka taea tonu te hoki ki tētahi.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Te tuku i ō whakaahua kua penapenahia (commit) mai i tēnei rorohiko ki te tārua tiritahi ki runga ipurangi, pēnei i a GitHub, kia whai tārua ai, kia taea hoki e ētahi atu te tiki."},{"id":"merge","g":"build","word":"Merge","text":"Te whakakotahi i ngā rerekētanga mai i tētahi manga ki tētahi atu, i te nuinga o te wā ki te putanga matua."},{"id":"pr","g":"build","word":"Pull request","text":"Te tono kia tirohia, kia whakakotahitia hoki ngā rerekētanga o tētahi manga ki te putanga matua. E kīia ana e ētahi pae he merge request.","also":["PR","PRs","merge request","tono whakakotahi"]},{"id":"refactor","g":"build","word":"Refactor","text":"Te whakapai i te waehere me te kore e panoni i tāna mahi: ngā kōpaki iti ake, ngā ingoa mārama ake, he iti ake te tuaruatanga."},{"id":"bug","g":"build","word":"Bug","text":"He mea kāore e mahi pērā i te tika.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Arotake a te hoa","text":"He kanohi tuarua: ka tirotiro tētahi atu, ehara i te kaituhi, i te mahi i mua i tōna tae ki a koe, kia iti ake ai ngā hapa ka pahemo. I AI-gile ka tirotiro tētahi atu AI i ia kāri.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Waehere (Code)","text":"Ngā tohutohu kua tuhia e kī ana ki te rorohiko he aha tāna mahi. E kīia ana hoki he source code.","also":["waehere","source code","waehere pūtake"],"noTip":1},{"id":"proglang","g":"build","word":"Reo hōtaka (Programming language)","text":"He reo mō te tuhi waehere, pēnei i a JavaScript, Python, Java rānei. He pai ake ētahi mō ētahi momo mahi.","also":["reo hōtaka","programming languages"]},{"id":"developer","g":"build","word":"Kaiwhakawhanake (Developer, dev)","text":"Te tangata e tuhi ana, e whakarerekē ana hoki i te waehere. E kīia ana hoki he programmer, he software engineer rānei.","also":["kaiwhakawhanake","developer","developers","programmer","programmers","software engineer","kaituhi hōtaka"]},{"id":"software","g":"build","word":"Pūmanawa (Software)","text":"Ngā hōtaka e rere ana i runga i ngā rorohiko me ngā waea, kaua ko ngā pūrere tonu (te pūmārō, hardware).","noTip":1},{"id":"app","g":"build","word":"Taupānga (App)","text":"He kupu poto mō application: he hōtaka e whakamahia ana e te tangata hei whakaoti i tētahi mahi, i runga i te waea, i te rorohiko, i te pūtirotiro tukutuku rānei.","also":["taupānga","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Taupānga tukutuku (Web app)","text":"He taupānga e rere ana i roto i te pūtirotiro tukutuku, nō reira kāore he mea hei tāuta.","also":["taupānga tukutuku","web apps","web application"]},{"id":"frontend","g":"build","word":"Taha mua (Front end)","text":"Te wāhanga o te taupānga e kitea ana, e pātōhia ana e koe: ngā mata, ngā pātene me ngā kupu, i te nuinga o te wā kei tō pūtirotiro.","also":["taha mua","front-end","frontend"]},{"id":"backend","g":"build","word":"Taha muri (Back end)","text":"Te wāhanga kei muri i te atamira o te taupānga e pupuri ana i ngā raraunga, e mahi ana hoki ina pātō koe i tētahi mea, pēnei i te tirotiro i tō kupuhipa.","also":["taha muri","back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack (taha mua me taha muri)","text":"Te mahi i te taha mua me te taha muri e rua.","also":["full-stack","taha mua me taha muri"]},{"id":"ui","g":"build","word":"Tapaetanga kaiwhakamahi (User interface, UI)","text":"Te mea e kitea ana, e whakamahia ana e te tangata i te mata: te whakatakotoranga, ngā pātene, ngā tahua me ngā kupu.","also":["UI","user interface","tapaetanga kaiwhakamahi"]},{"id":"ux","g":"build","word":"Wheako kaiwhakamahi (User experience, UX)","text":"Te āhua o te whakamahi i tētahi mea: he māmā, he mārama, he āhuareka; he pōrearea, he pōturi rānei.","also":["UX","user experience","wheako kaiwhakamahi"]},{"id":"accessibility","g":"build","word":"Te whai wāhi (Accessibility, a11y)","text":"Te whakarite kia taea e te katoa te whakamahi i ngā mea, tae atu ki te hunga kāore e tino kite, kāore e taea e rātou te whakamahi i te kiore, e whakamahi ana rānei i te kaipānui mata.","also":["te whai wāhi","a11y"]},{"id":"responsive","g":"build","word":"Hoahoa urupare (Responsive design)","text":"Te whakarite kia hāngai, kia pai hoki te mahi o ngā whārangi i runga i ngā rahi mata katoa, mai i te waea ki te mata nui.","also":["hoahoa urupare"]},{"id":"designsys","g":"build","word":"Pūnaha hoahoa (Design system)","text":"He pūkete tiritahi o ngā tae, ngā momotuhi, ngā pātene me ngā ture, kia rite ai te āhua me te mahi o ia mata.","also":["pūnaha hoahoa","design systems"]},{"id":"architecture","g":"build","word":"Hoahoanga (Architecture)","text":"Te āhua whānui o tētahi pūnaha: ko ēhea ngā wāhanga matua, me pēhea tā rātou kōrero ki a rātou anō."},{"id":"database","g":"build","word":"Pātengi raraunga (Database, DB)","text":"He pātaka kua whakaritea mō ngā mōhiohio, pēnei i tētahi ripanga tino kaha ka taea e te taupānga te pānui, te whakarerekē hoki.","also":["pātengi raraunga","database","databases","DB"]},{"id":"schema","g":"build","word":"Hoahoa pātengi raraunga (Database schema)","text":"Te whakatakotoranga o tētahi pātengi raraunga: he aha ngā ripanga mōhiohio kei roto, he aha hoki ngā mea ka haere ki ia ripanga.","also":["hoahoa pātengi raraunga","schema"]},{"id":"sql","g":"build","word":"SQL","text":"He kupu poto mō structured query language: te reo e whakamahia ana hei pātai mōhiohio i ngā pātengi raraunga maha, hei whakarerekē rānei i a rātou.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Raraunga (Data)","text":"Ngā mōhiohio e pupuritia ana e te rorohiko, pēnei i ngā ingoa, ngā ota, ngā tautuhinga rānei.","also":["raraunga","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Tūmau (Server)","text":"He rorohiko e kā tonu ana, e whakautu ana ki ngā tono a ētahi atu rorohiko, pēnei i te tuku i tētahi whārangi tukutuku ina toro atu koe.","also":["tūmau","servers"]},{"id":"client","g":"build","word":"Kiritaki (Client)","text":"Te taha e tono ana i tētahi mea, te nuinga o te wā ko tō pūtirotiro, ko tō taupānga rānei, e kōrero ana ki tētahi tūmau. I te pakihi ka tikanga hoki ko te kiritaki.","also":["kiritaki","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"He kupu poto mō application programming interface: he tahua tono ka taea e tētahi hōtaka te tuku ki tētahi atu, pēnei i te pātai ki tētahi ratonga huarere mō te matapae o te rā nei.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Pito mutunga (Endpoint)","text":"Tētahi tūemi o te tahua a tētahi API: he wāhitau tukutuku ka taea e tētahi hōtaka te karanga hei tiki, hei tuku rānei i tētahi mea.","also":["pito mutunga","endpoints"]},{"id":"integration","g":"build","word":"Whakaurunga (Integration)","text":"Te hono i ngā pūnaha e rua kia mahi tahi, pēnei i tō toa e tuku ana i ngā ota ki tō pūmanawa kaute.","also":["whakaurunga","integrations"]},{"id":"webhook","g":"build","word":"Webhook (matau tukutuku)","text":"He karere ka tukuna e tētahi pūnaha ki tētahi atu mā tōna anō i te wā tonu ka puta tētahi mea, pēnei i “kua tae mai te utu”.","also":["webhook","webhooks"]},{"id":"library","g":"build","word":"Pātaka waehere (Library)","text":"He waehere kua oti kē te tuhi e tētahi atu, ka taea e koe te whakamahi anō, kaua e tuhi mā koe anō.","also":["pātaka waehere","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Anga mahi (Framework)","text":"He hanganga kua oti kē mō te hanga taupānga e whakatau ana i te nuinga o te whakatakotoranga o te waehere, pēnei i te anga whare ka whakakīia e koe.","also":["anga mahi","frameworks"]},{"id":"sdk","g":"build","word":"Kete whakawhanake pūmanawa (Software development kit, SDK)","text":"He pouaka taputapu, waehere me ngā tauira mō te hanga pūmanawa mō tētahi pūhara, ratonga rānei.","also":["SDK","SDKs","kete whakawhanake pūmanawa"]},{"id":"softdep","g":"build","word":"Whakawhirinaki pūmanawa (Software dependency)","text":"He pātaka waehere, he taputapu rānei e hiahiatia ana e tō waehere kia mahi ai. He mea nui kia hou tonu ēnei mō te haumaru.","also":["whakawhirinaki pūmanawa","software dependencies"]},{"id":"package","g":"build","word":"Pūkete (Package)","text":"He paihere waehere kua oti kē, ka taea te tāuta me te whakamahi i roto i tētahi kaupapa.","also":["pūkete","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Kaiwhakahaere pūkete (Package manager)","text":"He taputapu e tiki ana, e whakahōu ana hoki i ngā pūkete e whirinaki ai tō waehere. Ko npm tētahi e whakamahia nuitia ana.","also":["kaiwhakahaere pūkete","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Te taputapu e whakamahia whānuitia ana hei pupuri i te hītori o ngā rerekētanga waehere, mā ngā commit me ngā branch."},{"id":"github","g":"build","word":"GitHub","text":"He pae tukutuku e pupuri ana i ngā Git repo ki runga ipurangi, kia taea ai e ngā rōpū te tiritiri waehere, te arotake rerekētanga me te aroturuki mahi."},{"id":"vcs","g":"build","word":"Whakahaere putanga (Version control)","text":"Te pupuri i te hītori katoa o ia rerekētanga ki ngā kōnae, kia kite ai koe ko wai nāna i whakarerekē he aha, ā, ka taea te hoki ki muri mēnā e tika ana. Ka mahi a Git i tēnei.","also":["whakahaere putanga","source control","version control system"]},{"id":"clone","g":"build","word":"Tārua (Clone)","text":"Te hanga i tētahi tārua tino katoa o tētahi repo, me tōna hītori, ki tō rorohiko.","also":["tārua","cloned","cloning"]},{"id":"pull","g":"build","word":"Tiki (Pull)","text":"Te tiki mai i ngā commit hou rawa mai i te tārua tiritahi (pēnei i GitHub) ki tō rorohiko. Te tauaro o push.","also":["tiki","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Manga matua (Main branch)","text":"Te putanga ōkawa o te waehere e mahi ai te katoa, e kīia ana he main, he master rānei.","also":["manga matua","master branch"]},{"id":"conflict","g":"build","word":"Taupatupatu whakakotahi (Merge conflict)","text":"Ina pā ngā rerekētanga e rua ki ngā rārangi kotahi i ngā tikanga rerekē, nō reira kāore e taea e te rorohiko te whakakotahi, ā, me kōwhiri te tangata.","also":["taupatupatu whakakotahi","merge conflicts"]},{"id":"diff","g":"build","word":"Rerekētanga (Diff)","text":"He tirohanga e whakaatu tika ana he aha i rerekē i waenga i ngā putanga e rua: ngā rārangi kua tāpiria me ngā rārangi kua tangohia.","also":["rerekētanga","diffs"]},{"id":"fork","g":"build","word":"Kape wehe (Fork)","text":"Tō ake tārua o te repo a tētahi atu, ka taea e koe te whakarerekē me te kore e pā ki tāna.","also":["kape wehe","forks","forked"]},{"id":"script","g":"build","word":"Tuhinga mahi (Script)","text":"He hōtaka poto e mahi ana i tētahi mahi mā tōna anō, pēnei i te whakapai i ngā kōnae, i te tīmata rānei i te taupānga.","also":["tuhinga mahi","scripts"],"noTip":1},{"id":"build","g":"build","word":"Hanga (Build)","text":"Te huri i te waehere hei mea e rite ana ki te rere, te hua rānei kua rite ki te rere.","also":["hanga","builds"],"noTip":1},{"id":"compile","g":"build","word":"Whakahuri (Compile)","text":"Te whakamāori i te waehere i tuhia e te tangata hei āhua ka taea e te rorohiko te rere tika.","also":["whakahuri","compiler"]},{"id":"cli","g":"build","word":"Rārangi whakahau (Command line, CLI)","text":"He matapihi kuputuhi e patopato ai koe i ngā tohutohu mō te rorohiko, kaua e pātō. E kīia ana hoki he terminal.","also":["rārangi whakahau","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Whirihora (Configuration, config)","text":"Ngā tautuhinga e whakahaere ana i te āhua o te mahi a te pūmanawa, ka puritia wehe i te waehere kia ngāwari ai te whakarerekē.","also":["whirihora","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Taurangi taiao (Environment variable)","text":"He tautuhinga ka hoatu ki tētahi hōtaka ina tīmata, e whakamahia ana mō ngā wāhitau, mō ngā kupuhipa rānei, kia kore ai e tuhia ki te waehere.","also":["taurangi taiao","environment variables","env var"]},{"id":"debugging","g":"build","word":"Whakatika pārurenga (Debugging)","text":"Te rapu he aha i kore ai e mahi tētahi mea, me te whakatika.","also":["whakatika pārurenga","debug","debugged"]},{"id":"pairing","g":"build","word":"Tuhi hōtaka takirua (Pair programming)","text":"Tokorua (he tangata me tētahi AI rānei) e mahi tahi ana i te waehere kotahi: ko tētahi e patopato ana, ko tētahi e tirotiro ana.","also":["tuhi hōtaka takirua","pairing"]},{"id":"docs","g":"build","word":"Tuhinga (Documentation, docs)","text":"Ngā whakamārama kua tuhia e pā ana ki te āhua o te mahi, te whakamahi rānei o tētahi mea.","also":["tuhinga","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Te kōnae tuatahi hei pānui i roto i tētahi repo: he aha te kaupapa, ā, me pēhea te whakarite kia rere.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Pūnaha tawhito (Legacy system)","text":"He pūnaha tawhito e whakamahia tonutia ana, he uaua ki te whakarerekē, i te nuinga o te wā nā te mea he ruarua noa e mārama tonu ana ki taua pūnaha.","also":["pūnaha tawhito","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Nama hangarau (Technical debt)","text":"Ngā ara poto e penapena wā ana ināianei, engari ka pōturi ake ngā panonitanga ā muri ake, pēnei i tētahi nama ka tipu tōna huamoni. Mā te refactoring e utu whakaiti.","also":["nama hangarau","tech debt"]},{"id":"test","g":"test","word":"Test","text":"He tirotiro mēnā e mahi ana tētahi mea i te āhua e tika ana. Ka whakahaerehia ētahi whakamātau e te rorohiko mā tōna anō i ia wā ka rerekē te waehere; ko ētahi atu ko tō whakamātau i tētahi kāri kua oti i mua i tō whakaae.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Te kupu poto mō quality assurance: ngā mea katoa e mahia ana kia tika te mahi i mua i te whakaputa. I AI-gile ko te tikanga ko ngā tirotiro aunoa: ina whero te QA, kua rahua tētahi mea, ā, kāore e taea te whakaputa kia whakatikatia rā anō.","also":["arowhai kounga","quality checks"]},{"id":"testpile","g":"test","word":"Puranga whakamātautau","text":"Ngā kāri kua oti e tatari ana kia whakamātauria e koe, tētahi i muri i tētahi. Whakaaetia tētahi, whakahokia rānei me tētahi tuhipoka, ā, ka puta mai te mea e whai ake ana.","also":["test pile"]},{"id":"autotest","g":"test","word":"Whakamātau aunoa (Automated test)","text":"He tirotiro ka whakahaerehia e te rorohiko mā tōna anō i ia wā ka rerekē te waehere, hei hopu i ngā hapa i te wā moata.","also":["whakamātau aunoa","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Whakamātau ā-ringa (Manual test)","text":"He tangata e whakamātau ā-ringa ana i te mahi kia kite mēnā e mahi ana i te āhua e tika ana.","also":["whakamātau ā-ringa","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Whakamātau wae (Unit test)","text":"He tirotiro aunoa iti mō tētahi wāhanga waehere iti kotahi, wehe i ērā atu.","also":["whakamātau wae","unit tests"]},{"id":"integtest","g":"test","word":"Whakamātau whakaurunga (Integration test)","text":"He tirotiro mēnā e pai ana te mahi tahi a ētahi wāhanga maha, kaua ko te wāhanga kotahi anake i te wā kotahi.","also":["whakamātau whakaurunga","integration tests"]},{"id":"endtoend","g":"test","word":"Whakamātau mai i te tīmatanga ki te mutunga (End-to-end test, E2E)","text":"He whakamātau e rite ana ki tētahi kaiwhakamahi tūturu mai i te tīmatanga ki te mutunga, pēnei i te haina mai, te hoko me te utu.","also":["E2E","end-to-end tests","whakamātau tīmata-ki-te-mutunga"]},{"id":"uat","g":"test","word":"Whakamātau whakaae kaiwhakamahi (User acceptance testing, UAT)","text":"Ka whakamātau te hunga i tono i te mahi mā rātou anō, ā, ka kī mēnā e rite ana ki ā rātou hiahia. Ko te Puranga whakamātautau a AI-gile tāna momo o tēnei.","also":["UAT","acceptance testing","whakamātau whakaae"]},{"id":"regression","g":"test","word":"Whakamuri (Regression)","text":"Tētahi mea i mahi i mua engari kua pakaru i muri i te rerekētanga. Ka tirotiro ngā regression test mēnā e mahi tonu ana ngā mea tawhito.","also":["whakamuri","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Whakamātau auahi (Smoke test)","text":"He tirotiro tino tere mēnā e mahi ana ngā mea matua, hei tauira i muri tonu i te whakaputanga o tētahi rerekētanga. Ki te rahua, kati, tirohia.","also":["whakamātau auahi","smoke tests"]},{"id":"exploratory","g":"test","word":"Whakamātau rapu (Exploratory testing)","text":"Te whakamātau noa i te hua me te tūhura i a ia i ngā huarahi maha, hei rapu raru ka ngaro i ngā tirotiro kua whakaritea.","also":["whakamātau rapu","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Take whakamātau (Test case)","text":"Kotahi te āhuatanga kua tuhia hei whakamātau: ngā takahanga me te mea e tika ana kia puta.","also":["take whakamātau","test cases"]},{"id":"coverage","g":"test","word":"Whānuitanga whakamātau (Test coverage)","text":"Te nui o te waehere e tirohia ana e ngā whakamātau aunoa. Ko te nui ake, ko te haumaru ake i te nuinga o te wā, engari kāore te whānuitanga teitei anake e whakaatu he pai te mahi.","also":["whānuitanga whakamātau","code coverage"]},{"id":"testdata","g":"test","word":"Raraunga whakamātau (Test data)","text":"Ngā mōhiohio tauira i hangaia noa hei whakamahi i te wā whakamātau, kia kore ai e puta ngā taipitopito muna o tētahi tangata pono.","also":["raraunga whakamātau","test fixtures"]},{"id":"edgecase","g":"test","word":"Take tapa (Edge case)","text":"He āhuatanga rerekē i ngā tapa, pēnei i tētahi puka kau, i tētahi ingoa he tohu apostrophe tōna rānei, ā, ko ēnei ngā wāhi e pakaru ai ngā mea i te nuinga o te wā.","also":["take tapa","edge cases"]},{"id":"happypath","g":"test","word":"Ara harikoa (Happy path)","text":"Te ara noa e tika ana ngā mea katoa. Ko te whakamātau pai ka whakamātau hoki i ngā ara kāore i te harikoa."},{"id":"perftest","g":"test","word":"Whakamātau whakatutukinga (Performance testing)","text":"Te tirotiro i te tere o tētahi mea me tōna kaha ki te ū i raro i te pēhanga.","also":["whakamātau whakatutukinga","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Whakamātau uta (Load testing)","text":"Te tirotiro i te ū o tētahi pūnaha ina tokomaha ngā tāngata e whakamahi ana i te wā kotahi.","also":["whakamātau uta","load test","load tests"]},{"id":"sectest","g":"test","word":"Whakamātau haumaru (Security testing)","text":"Te rapu i ngā ngoikoretanga e āhei ai pea tētahi ki te whakamahi hē i tētahi pūnaha, ki te kite rānei i ngā mea kāore e tika kia kitea e ia.","also":["whakamātau haumaru","security test","security tests"]},{"id":"accesstest","g":"test","word":"Whakamātau whai wāhi (Accessibility testing)","text":"Te tirotiro mēnā ka taea e ngā tāngata he rerekē ō rātou āheinga te whakamahi i te hua, tae atu ki te kaipānui mata, ki te papa pātuhi anake rānei.","also":["whakamātau whai wāhi","accessibility test"]},{"id":"linting","g":"test","word":"Tirotiro waehere (Linting)","text":"He tirotiro aunoa e kite ana i ngā hapa pea me te tuhi kāore i te nahanaha i roto i te waehere, pēnei i te kaitirotiro takikupu mō ngā hōtaka.","also":["tirotiro waehere","linter","lint"]},{"id":"static","g":"test","word":"Tātari pūmau (Static analysis)","text":"Te tirotiro i te waehere mō ngā raru mā te pānui aunoa, me te kore e whakarere.","also":["tātari pūmau","static code analysis"]},{"id":"flaky","g":"test","word":"Whakamātau kōtiti (Flaky test)","text":"He whakamātau ka tutuki i ētahi wā, ka rahua i ētahi wā, kāore he take mārama, nō reira kāore e taea te tino whakawhirinaki.","also":["whakamātau kōtiti","flaky tests"]},{"id":"repro","g":"test","word":"Whakaputa anō (Reproduce, repro)","text":"Te whakaputa anō i tētahi pārurenga ā-hiahia mā te whai i ngā takahanga rite, kia taea ai te ako me te whakatika. Ko te tuhi i aua takahanga te wāhanga whai hua rawa o te pūrongo pārurenga.","also":["repro","reproduce","steps to reproduce","ngā takahanga whakaputa anō"]},{"id":"severity","g":"test","word":"Taumata kino (Severity)","text":"Te kino o te pānga o tētahi raru, mai i tētahi whakahōhā iti tae noa ki te tū o ngā mea katoa.","also":["taumata kino","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Te tārua i tētahi putanga hou o te pūmanawa ki ngā rorohiko e whakahaere ana i a ia, pēnei i tētahi tārua whakamātau, i te ratonga ora rānei."},{"id":"release","g":"change","word":"Tukunga","text":"He paihere mahi kua oti, he ingoa tōna, ka haere ora tahi, me ngā kōrero poto mō ngā mea i panoni. Ka tuhia e 🚀 Tukunga ngā kōrero mai i ngā kāri kua oti.","also":["ngā tukunga","release","releases"]},{"id":"rollback","g":"change","word":"Huri whakamuri","text":"Te hoki ki te putanga whakamutunga i mahi ina raru i te putanga hou. I AI-gile, ka kohikohi te Huri whakamuri i ngā takahanga whakakore kua tuhia ki ia rerekētanga hei rārangi tirotiro kotahi.","also":["whakahoki","rollback","roll back"]},{"id":"live","g":"change","word":"Haere ora","text":"Te putanga tūturu e whakamahia ana e te tangata, ehara i te kape hei whakamātau. E kīia ana hoki e ngā kaiwhakawhanake ko te production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Panonitanga","text":"He panonitanga kua whakamaheretia ki tētahi mea e whakawhirinaki ana te tangata, kua tuhia i mua: he aha, he aha ai, te tūraru, āhea, me pēhea te huri whakamuri. Tīmatahia mā 🔀 Whakaara panonitanga.","also":["ngā panonitanga","tono panonitanga","huringa"],"noTip":1},{"id":"risk","g":"change","word":"Tūraru","text":"He mea ka hē pea, kua tohua he kaute mō te tūponotanga me te kino ka puta. Ka puritia e ⚠️ Ngā tūraru ki te rārangi kotahi, ko te kaute teitei rawa i mua, he rā tō ia mea kia tirohia anō.","also":["ngā tūraru","tūpono","rēhita tūraru"]},{"id":"chgwin","g":"change","word":"Matapihi panonitanga","text":"Ngā wā e āhei ai ngā panonitanga te haere ora, pēnei i tētahi ahiahi Tūrei mārie. I waho i te matapihi, kāore e taea te whakaoti i tētahi kāri panonitanga, ki te kore he ohotata.","also":["matapihi","ngā matapihi panonitanga"]},{"id":"gonogo","g":"change","word":"Haere / kaua e haere","text":"He tirotiro whakamutunga i mua tonu i te whakaputanga o tētahi rerekētanga: ka kī ia tangata me whakaae, “Haere”, “Kaua e haere” rānei. Ka haere anake ina kī te katoa “Haere”.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Whakaaetanga","text":"Te tatari ki tētahi āe i mua i te tīmatanga o te mahi. Ka tatari tētahi kāri nā tētahi hoa i whakaara, he panonitanga rānei, i ✅ Ngā whakaaetanga kia whakaae, kia whakakāhore rānei koe.","also":["ngā whakaaetanga"]},{"id":"quiettime","g":"change","word":"Wā ata noho","text":"He wā, pēnei i te wā o tētahi pāho ora, o tētahi whakaaturanga, o te pō rānei, kāore he mea e whakaputaina. Ka haere tonu ngā rōpū i te mahi me te whakamātau, engari ka tatari te whakaputa kia mutu rā anō. I ētahi atu wāhi e kīia ana he change freeze.","also":["ngā wā ata noho","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"He tikanga mahi e mahi ai te hunga hanga pūmanawa me te hunga whakahaere i taua pūmanawa hei rōpū kotahi, me te nui o te aunoa, kia whakaputaina ai ngā rerekētanga i ngā wā maha, i runga i te haumaru."},{"id":"cicd","g":"change","word":"CI/CD (whakakotahi me te tuku tonu)","text":"Ka whakakotahitia ngā rerekētanga a te katoa ki te putanga matua i ngā wā maha, ā, ka tirotirohia aunoatia i ia wā (continuous integration), kia rite tonu ai te pūmanawa ki te whakaputa mā te pēhi i te pātene kotahi (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Whakaputa tonu (Continuous deployment)","text":"Kotahi te takahanga ki mua atu i te continuous delivery: ka puta aunoa ki te ora ia rerekētanga ka tutuki i ngā tirotiro, kāore he pātene hei pēhi.","also":["whakaputa tonu","continuous deployments"]},{"id":"pipeline","g":"change","word":"Paipa mahi (Pipeline)","text":"Te raupapa aunoa o ngā takahanga e haere ai tētahi rerekētanga i tōna ara ki te ora, pēnei i te hanga, te whakamātau, kātahi ka tuku.","also":["paipa mahi","pipelines"]},{"id":"environment","g":"change","word":"Taiao (Environment)","text":"Kotahi te tārua wehe o te pūnaha mō tētahi take, pēnei i tētahi hei hanga, i tētahi hei whakamātau, me tērā e ora ana.","also":["taiao","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Taiao whakawhanake (Development environment)","text":"Te tārua e mahi ai te kaiwhakawhanake, i te nuinga o te wā kei tōna ake rorohiko, ā, mēnā ka pakaru ngā mea, kāore tētahi e pāngia.","also":["taiao whakawhanake","dev environment"]},{"id":"testenv","g":"change","word":"Taiao whakamātau (Test environment)","text":"He tārua wehe o te pūnaha e whakamahia ana mō te whakamātau anake, kia kore ai e pā ki te ratonga pono.","also":["taiao whakamātau","test environments"]},{"id":"staging","g":"change","word":"Taiao whakarite (Staging)","text":"Te tārua whakamutunga kua whakaritea kia ōrite ki te pūnaha ora, mō te tirotiro whakamutunga i mua i te whakaputanga o tētahi rerekētanga.","also":["taiao whakarite","staging environment"]},{"id":"artifact","g":"change","word":"Hua hanga (Build artifact)","text":"Te kōnae, te paihere rānei ka puta mai i tētahi hanga, kua rite hei penapena, hei tirotiro, hei whakaputa rānei.","also":["hua hanga","build artifacts"]},{"id":"hotfix","g":"change","word":"Whakatika ohorere (Hotfix)","text":"He whakatika ohorere ka whakaputaina tere, i waho i te mahere noa, nā te mea kua pakaru tētahi mea nui.","also":["whakatika ohorere","hotfixes"]},{"id":"patch","g":"change","word":"Papaki (Patch)","text":"He whakahōu iti e whakatika ana i tētahi pārurenga, e kati ana rānei i tētahi poka haumaru. He mea nui te tāuta tere i ngā papaki haumaru.","also":["papaki","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Tau putanga (Version number)","text":"He tapanga pēnei i a 2.4.1 e kī ana ko tēhea te whakaputanga kei a koe. Te nuinga o te wā ka rerekē te tau tuatahi mō ngā rerekētanga nui, te tau whakamutunga mō ngā whakatika iti.","also":["tau putanga","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Tuhipoka whakaputanga (Release notes)","text":"He rārangi poto, māmā hoki o ngā mea i rerekē i roto i tētahi whakaputanga, mā te hunga e whakamahi ana, tae atu ki ngā whakatika me ngā here e mōhiotia ana. E kīia ana hoki he changelog.","also":["tuhipoka whakaputanga","changelog","change log"]},{"id":"flag","g":"change","word":"Pere āhuatanga (Feature flag)","text":"He pana whakakā-whakaweto mō tētahi āhuatanga, kia puta huna ai te mahi hou ki te ora, ā, ka taea te whakakā (te whakaweto anō rānei) me te kore whakaputanga hou.","also":["pere āhuatanga","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Whakatika whakamua (Roll forward)","text":"Te whakatika i tētahi whakaputanga kino mā te tuku tere i tētahi putanga hou kua whakatikatia, kaua e hoki ki te mea tawhito.","also":["whakatika whakamua","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Whakaputa kānari (Canary release)","text":"Te tuku i tētahi rerekētanga ki tētahi rōpū iti i te tuatahi, ā, ki te katoa anake ina kitea he pai. I tapaina ki ngā kānari i kawea ki raro i te whenua e ngā kaikeri hei whakatūpato moata.","also":["whakaputa kānari","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Whakaputa kikorangi-kākāriki (Blue-green deployment)","text":"Te pupuri i ngā tārua e rua o te pūnaha ora, ā, ka huri i te tangata ki te mea hou i te wā kotahi, kia taea ai te hoki tonu mēnā ka hē.","also":["whakaputa kikorangi-kākāriki","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Whakaputa kāore he wā tū (Zero-downtime deployment)","text":"Te whakaputa i tētahi putanga hou me te kore e mutu te ratonga mō ōna kaiwhakamahi.","also":["whakaputa kāore he wā tū","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Whakamana rerekētanga (Change enablement)","text":"Te āwhina i ngā rerekētanga kia angitu: te ine i te tūraru, te whiwhi i te whakaaetanga tika me te kōwhiri i tētahi wā pai. E kīia ana hoki he change management.","also":["whakamana rerekētanga","change management"]},{"id":"cab","g":"change","word":"Poari tohutohu rerekētanga (Change advisory board, CAB)","text":"He rōpū e tirotiro ana i ngā rerekētanga nui, ā, ka whakatau mēnā ka haere whakamua, āhea hoki.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Rerekētanga paerewa (Standard change)","text":"He rerekētanga tūraru iti ka mahia i te huarahi kotahi kua whakamātauhia i ia wā, nō reira kua whakaaetia i mua.","also":["rerekētanga paerewa","standard changes"]},{"id":"normchange","g":"change","word":"Rerekētanga noa (Normal change)","text":"He rerekētanga me tirotiro, me whakaae i mua i tōna haere whakamua.","also":["rerekētanga noa","normal changes"]},{"id":"emergchange","g":"change","word":"Rerekētanga ohorere (Emergency change)","text":"He rerekētanga me puta tonu hei whakatika, hei ārai rānei i tētahi raru nui, me tētahi whakaaetanga tere ake e hāngai ana.","also":["rerekētanga ohorere","emergency changes"]},{"id":"automation","g":"change","word":"Whakaaunoa (Automation)","text":"Te whakarite kia mahia e te rorohiko tētahi mahi tukurua mā tōna anō, kia tere ake ai, kia ōrite ai hoki te mahi i ia wā.","also":["whakaaunoa","automated"],"noTip":1},{"id":"infra","g":"change","word":"Hanganga tūāpapa (Infrastructure)","text":"Ngā mīhini, ngā whatunga me ngā ratonga e rere ai te pūmanawa.","also":["hanganga tūāpapa","infra"]},{"id":"iac","g":"change","word":"Hanganga tūāpapa hei waehere (Infrastructure as code, IaC)","text":"Te whakaahua i ō tūmau me ō tautuhinga i roto i ngā kōnae e pupuritia ana i te taha o te waehere, kia taea ai te hanga anō kia rite tonu i ia wā.","also":["IaC"]},{"id":"cloud","g":"change","word":"Kapua (Cloud)","text":"Te reti rorohiko, rokiroki me ngā ratonga mai i tētahi kaiwhakarato nui mā te ipurangi, kaua ko ōu ake mīhini.","also":["kapua","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Kaiwhakarato kapua (Cloud provider)","text":"He kamupene e reti ana i te kaha rorohiko mā te ipurangi, pēnei i a Amazon Web Services (AWS), Microsoft Azure, Google Cloud rānei.","also":["kaiwhakarato kapua","cloud providers"]},{"id":"hosting","g":"change","word":"Manaaki tūmau (Hosting)","text":"Te wāhi e noho ana, e rere ana tō taupānga, tō pae tukutuku rānei kia taea ai e te tangata te toro atu, i te nuinga o te wā ka retia mai i tētahi kamupene.","also":["manaaki tūmau"]},{"id":"domain","g":"change","word":"Ingoa rohe (Domain name)","text":"Te wāhitau tukutuku e patopatohia ana e te tangata, pēnei i a example.com. Ka retia e koe ia tau, nō reira me whakahōu.","also":["ingoa rohe","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"He kupu poto mō domain name system: te pukapuka wāhitau o te ipurangi, ka huri i tētahi ingoa pēnei i a example.com hei wāhitau o te rorohiko tika.","also":["domain name system"]},{"id":"container","g":"change","word":"Ipu pupuri (Container)","text":"He pūkete kua hiri e mau ana i tētahi taupānga me ngā mea katoa e hiahiatia ana e ia, kia ōrite tonu tana rere i runga i ngā rorohiko katoa. Ko Docker te taputapu e tino mōhiotia ana.","also":["ipu pupuri","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Rorohiko mariko (Virtual machine, VM)","text":"He rorohiko pohewa e rere ana i roto i tētahi rorohiko tūturu, kia taea ai e tētahi mīhini nui te mahi hei mīhini maha.","also":["VM","VMs","virtual machines","rorohiko mariko"]},{"id":"serverless","g":"change","word":"Kore tūmau (Serverless)","text":"Te whakahaere i te waehere me te kore e tiaki i ngā tūmau mā koe anō: ka whakahaere te kaiwhakarato ina hiahiatia, ā, ka utu koe mō tāu i whakamahi ai."},{"id":"lb","g":"change","word":"Kaiwhakataurite uta (Load balancer)","text":"Te mea e tohatoha ana i ngā manuhiri ki ngā tūmau maha, kia kore ai tētahi e taumaha rawa.","also":["kaiwhakataurite uta","load balancers"]},{"id":"cache","g":"change","word":"Pātaka tere (Cache)","text":"He pātaka ngāwari o ngā hua o nā tata nei, ka puritia ki te taha, kia kore ai e tikina anō, e tātaihia anō rānei te mea kotahi. Mā te muku i a ia ka whakatika pea i ngā whārangi he āhua tawhito.","also":["pātaka tere","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Whatunga tuku ihirangi (Content delivery network, CDN)","text":"He huinga tūmau puta noa i te ao e pupuri ana i ngā tārua o ō whārangi me ō pikitia tata ki ō manuhiri, kia tere ai te utanga.","also":["CDN","whatunga tuku ihirangi"]},{"id":"migration","g":"change","word":"Nekehanga (Migration)","text":"Te nekeneke i ngā raraunga, i ngā pūnaha rānei mai i tētahi whirihora tawhito ki tētahi hou, te whakarerekē tūpato rānei i te whakatakotoranga o tētahi pātengi raraunga.","also":["nekehanga","migrations","database migration"]},{"id":"service","g":"run","word":"Ratonga","text":"He mea nāu i hanga e whakawhirinaki ana te tangata, pēnei i te paetukutuku, i te taupānga rānei, e tiakina ana kia mahi tonu. Tīkina “He ratonga tēnei kaupapa”, ka kī ai he aha tāna e tuku ana, ko wai e whakamahi ana, ko wai kei te on-call.","also":["ngā ratonga","service"]},{"id":"uptimepct","g":"run","word":"Wā e rere ana (Uptime)","text":"Te nui o te wā e mahi ana tētahi ratonga, hei ōrau i te nuinga o te wā. Ahakoa 99.9%, ka toe tonu kia 43 meneti pea te wā tū ia marama.","also":["wā e rere ana","uptime percentage"]},{"id":"uptime","g":"run","word":"Arowhai uptime","text":"He arowhai aunoa, ia meneti torutoru, kei te whakautu tonu tō ratonga. Ki te hapa i ētahi wā e hia nei i te rārangi, ka whakatuwhera a AI-gile i tētahi kāri aitua mā ōna anō.","also":["uptime checks","tirotiro wā e rere ana"]},{"id":"statuspage","g":"run","word":"Whārangi tūnga","text":"He whārangi tūmatanui e whakaatu ana mēnā kei te mahi tētahi ratonga (kākāriki, karaka, whero rānei) me te pānui hou rawa, kia taea e te hunga whakamahi te tirotiro, kaua e pātai.","also":["ngā whārangi tūnga","status page"]},{"id":"desk","g":"run","word":"Tēpu ratonga","text":"Te wāhi e tae mai ai ngā pātai me ngā pūrongo a te hunga e whakamahi ana i tō ratonga. Ka whakarōpūhia e AI-gile ia mea hei tono, hei aitua, hei whakaaro rānei, ā, ka kī mēnā he rite ki tētahi mea kua oti kē te pūrongo.","also":["ngā tēpu ratonga","tēpu āwhina","helpdesk"]},{"id":"svcrequest","g":"run","word":"Tono ratonga","text":"He tangata e tono ana i tētahi mea noa, pēnei i tētahi pūkete hou, i tētahi āwhina iti rānei, kaua ko te pūrongo kua pakaru tētahi mea. Ka tatari ki tōna wā; ko te aitua te tuatahi.","also":["ngā tono ratonga"]},{"id":"incident","g":"run","word":"Aitua","text":"Tētahi mea kua pakaru, kāore rānei e mahi pai ana mō te hunga e whakamahi ana i tēnei wā, pēnei i te pae tukutuku kua hinga, tino pōturi rānei. Ka peke te kāri aituā 🔥 i te rārangi: ko te whakahoki kia mahi anō te mea tuatahi.","also":["ngā aitua","incident"]},{"id":"major","g":"run","word":"Aitua nui","text":"He aitua nui: he tokomaha kua pāngia, he moni, he raraunga rānei kei te mōrearea. Ka whakanohoia e te pātene kotahi ngā rōpū katoa ki runga (kāhui), ka whakaohongia te tangata kei te on-call, ka tonoa he whakahou tūnga ia 30 meneti.","also":["ngā aitua nui","major incident"]},{"id":"oncall","g":"run","word":"On-call","text":"Ko koe te tangata ka whakautu ina pakaru tētahi mea, ahakoa i te pō. He mema rōpū on-call tō ia ratonga, ko ia te tuatahi ka whakaohongia mō ōna aitua.","also":["on call","kaimahi on-call"]},{"id":"replyby","g":"run","word":"Wā whakautu","text":"Te roa ka taea e tētahi kāri te tatari mō te whakautu tuatahi, hei tauira kotahi hāora mō tētahi aitua. I muri i tērā ka whiwhi karaka whero, kia kaua tētahi mea e wareware puku. Ka kīia hoki he whāinga whakautu.","also":["ngā wā whakautu","whāinga whakautu","response target"]},{"id":"postmortem","g":"run","word":"Arotake i muri i te aitua","text":"He titiro poto whakamuri i muri i tētahi aitua: te mea i pā, te mea i āwhina me te mea me panoni, me te kore whakahē i tētahi. Kāore e taea te kati i tētahi aitua mēnā kāore he arotake.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Raruraru","text":"Te take huna kei muri i tētahi aitua, i ētahi aitua rānei. Ka whakarōpū tētahi kāri 🧩 raruraru i ngā aitua e hoki mai tonu ana, kia kitea ai te take, kia whakatikahia mō ake tonu.","also":["raru","ngā raruraru","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Pūtake tūturu","text":"Te take tūturu i pakaru ai tētahi mea, ehara i te mea i kitea e koe e hē ana anake. Whakatikahia te pūtake tūturu, ā, ka mutu te hoki mai o te aitua.","also":["ngā pūtake tūturu","root cause"]},{"id":"workaround","g":"run","word":"Aukati","text":"He huarahi e mahi tonu ai ngā mea kia rite rā anō te whakatika tūturu, pēnei i te tīmata anō i tētahi mea ina mau. Ka tuhia ki te kāri raruraru kia kaua tētahi e whakaaro anō.","also":["ngā aukati","rongoā mō te wā","workaround"]},{"id":"knownerror","g":"run","word":"Hapa e mōhiotia ana","text":"He raru kua mārama te take engari kāore anō kia whakatikatia, i te nuinga o te wā me tētahi huarahi huri kua tuhia. Kei te 🧩 Hapa e mōhiotia ana te rārangi o ēnei, kia whakamahi ai te katoa i te huarahi huri, kaua e keri anō.","also":["ngā hapa e mōhiotia ana","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"He tohutohu hipanga i te hipanga hei whakatika i tētahi momo raru e mōhiotia ana, kia ōrite te mahi, kia tere, i ia wā. I muri i tētahi aitua nui ka taea e te rōpū te tūtohu i tētahi mā tō OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Taonga whirihoranga","text":"He mea kotahi e whakawhirinaki ana tō ratonga ki runga, pēnei i te tūmau, te rohe, te tiwhikete, te kī, te kaiwhakarato rānei. Ka whakarārangitia e 🗂️ Ngā taonga whirihoranga mō ia ratonga, kia kite koe he aha e pāngia ana e tētahi aitua, he aha me whakahou, me kape tiaki rānei.","also":["ngā taonga whirihoranga"]},{"id":"expiry","g":"run","word":"Rā pau","text":"Te rā ka mutu te mahi o tētahi mea ki te kore e whakahōungia, pēnei i te tiwhikete haumaru o tētahi pae tukutuku, i tōna wāhitau tukutuku rānei. Ka mātakitaki a AI-gile i ēnei rā, ā, ka hanga kāri kotahi hei whakahōu i ia tētahi 30 rā i mua, kia kore ai e mutu ohorere tētahi mea.","also":["ngā rā pau","pau","tirotiro rā pau"]},{"id":"backup","g":"run","word":"Kape tiaki","text":"He kape kua tiakina o ō raraunga mai i mua, hei whakawhirinaki mēnā ka ngaro, ka pakaru rānei tētahi mea. Ka hanga a AI-gile i tētahi kape tiaki o ō papa ia rā.","also":["tiaki","ngā kape tiaki","backup"]},{"id":"restore","g":"run","word":"Whakahoki mai","text":"Te whakahoki mai i ngā raraunga i tētahi kape tiaki. Ka whai tikanga tūturu te kape tiaki ina mōhio koe ka taea te whakahoki mai, nō reira he pai te whakamātau i ētahi wā.","also":["whakahokia mai","restore"]},{"id":"svcreview","g":"run","word":"Arotake ratonga","text":"He titiro whakamuri ki te marama kotahi o tētahi ratonga: ngā aitua i tuwhera, i whakatikahia, te tere o te whakautu ki te tangata, te wā e mahi ana, me ngā tohu i whakamahia. Ka whakaaturia e te Arotake ā-marama mō ia ratonga.","also":["ngā arotake ratonga","arotake ā-marama","ngā arotake ā-marama"]},{"id":"accessreview","g":"run","word":"Arotake urunga","text":"Te tirotiro ia 90 rā ko wai e āhei tonu ana ki te uru: ngā hononga tiritiri, ngā tūranga o ngā hoa me ngā kupuhipa me ngā kī kua penapenahia. Ka pupuri, ka tango rānei koe i ia tētahi, kia kore ai e noho tonu te urunga tawhito.","also":["ngā arotake urunga"]},{"id":"improvements","g":"run","word":"Rārangi whakapainga","text":"Ngā mea katoa i whakatau te rōpū kia pai ake, i te wāhi kotahi: ngā whakaaro retro, ngā mahi arotake me ngā whakatika raruraru, me te tūnga o ia mea. Kei raro i 📈 Whakapainga.","also":["ngā rārangi whakapainga","whakapainga"]},{"id":"tokencap","g":"run","word":"Tepe tohu","text":"He tepe ā-marama mō ngā tohu e whakaaetia ana kia whakamahia e ngā kaiwhakahaere o tētahi ratonga. Ka tae ki te 80% ka whiwhi koe i tētahi whakatūpato; ka tae ki te 100% ka tatari ā rātou mahi o muri ki te marama e heke mai, kia whakapikia rānei e koe te tepe.","also":["ngā tepe tohu"]},{"id":"svcmgmt","g":"run","word":"Whakahaere ratonga (Service management)","text":"Ngā mea katoa e pā ana ki te pupuri i tētahi ratonga kia whai hua, kia mahi hoki mō te hunga e whirinaki ana ki a ia, i ia rā, i ia rā.","also":["whakahaere ratonga"]},{"id":"itil","g":"run","word":"ITIL","text":"He aratohu e whakamahia whānuitia ana mō te whakahaere ratonga pai, e kapi ana i ngā mea pēnei i ngā aituā, ngā raru me ngā rerekētanga. I mua, ko te tikanga o te ingoa ko IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Whakahaere ratonga IT (IT service management, ITSM)","text":"Te whakahaere i te hangarau hei ratonga mō te tangata, me ngā huarahi mārama hei whakahaere i ngā tono, ngā aituā, ngā rerekētanga me ngā whakapainga.","also":["ITSM"]},{"id":"managed","g":"run","word":"Ratonga whakahaerehia (Managed service)","text":"He ratonga e whakahaerehia ana, e tiakina ana e tētahi atu mōu, i raro i tētahi whakaaetanga mō te pai o tana mahi.","also":["ratonga whakahaerehia","managed services"]},{"id":"svcowner","g":"run","word":"Kaipupuri ratonga (Service owner)","text":"Te tangata e kawe ana i te kawenga mō tētahi ratonga katoa: te pai o tana mahi, te utu, me tana whakapai ake.","also":["kaipupuri ratonga","service owners"]},{"id":"sla","g":"run","word":"Whakaaetanga taumata ratonga (Service level agreement, SLA)","text":"He oati tuhi ki ngā kiritaki mō te pai o te mahi a tētahi ratonga, pēnei i “e rere ana 99.9% o te wā”, i “ka whakautua i roto i te hāora kotahi” rānei, ā, i te nuinga o te wā ka whakahokia he moni mēnā ka takahia.","also":["SLA","SLAs","service level agreement","whakaaetanga taumata ratonga"]},{"id":"slo","g":"run","word":"Whāinga taumata ratonga (Service level objective, SLO)","text":"Te whāinga a te rōpū ake mō te pai o te mahi a tētahi ratonga i tētahi wā, i te nuinga o te wā ka whakaritea he paku kaha ake i te SLA hei haumaru.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Tohu taumata ratonga (Service level indicator, SLI)","text":"Te inenga tūturu ka whakatauritea e koe ki tētahi whāinga, pēnei i te ōrau o ngā toro i pai te utanga.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Te wātea (Availability)","text":"Mēnā ka taea e te tangata te whakamahi i tētahi ratonga ina hiahiatia, e inea ana hei uptime i te nuinga o te wā.","also":["te wātea","high availability"]},{"id":"downtime","g":"run","word":"Wā mutu (Downtime)","text":"Te wā kāore e mahi ana te ratonga, kua whakawetongia rānei, he mea whakarite, kāore rānei.","also":["wā mutu","down time"]},{"id":"errorbudget","g":"run","word":"Tahua hapa (Error budget)","text":"Te nui paku o te rahua e whakaaetia ana e tō whāinga pūmautanga. I te wā e toe ana, ka āhei koe ki te tūraru ki ngā rerekētanga; ina pau, ka āta haere koe.","also":["tahua hapa","error budgets"]},{"id":"outage","g":"run","word":"Wā pakaru (Outage)","text":"He wā e mutu ana te ratonga, e pakaru kino ana rānei mō ōna kaiwhakamahi.","also":["wā pakaru","outages"]},{"id":"degraded","g":"run","word":"Kua heke te kounga (Degraded)","text":"E mahi ana, engari kāore i te pai: e pōturi ana, kāore rānei ētahi wāhanga e mahi.","also":["kua heke te kounga","degraded service"]},{"id":"monitoring","g":"run","word":"Aroturuki (Monitoring)","text":"Te mātakitaki aunoa i tētahi ratonga i ngā wā katoa, kia kitea ai ngā raru, ko te mea pai, i mua i te kitenga a ngā kaiwhakamahi.","also":["aroturuki"]},{"id":"observability","g":"run","word":"Te āhei ki te tirotiro (Observability)","text":"Te kaha ki te mōhio he aha e haere ana i roto i tētahi pūnaha mai i waho, mā āna rātaka, āna tau me āna ara whai.","also":["te āhei ki te tirotiro","o11y"]},{"id":"log","g":"run","word":"Rātaka (Log)","text":"He rātaka haere tonu e tuhia ana e tētahi hōtaka mō āna mahi, e whakamahia ana hei mōhio he aha i hē ai.","also":["rātaka","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Ara whai (Trace)","text":"He rekoata o te haere a tētahi tono i roto i ngā wāhanga rerekē o tētahi pūnaha, takahanga ki te takahanga, e whakaatu ana i te wāhi i pōturi ai.","also":["ara whai","traces","tracing"]},{"id":"latency","g":"run","word":"Whakaroa (Latency)","text":"Te roa e whakautu ai tētahi mea, pēnei i te tatari i waenga i te pātō me te puta mai o te whārangi."},{"id":"alert","g":"run","word":"Whakatūpato (Alert)","text":"He karere aunoa e kī ana me aro tētahi mea, pēnei i te pae tukutuku kāore e whakautu.","also":["whakatūpato","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Ngenge whakatūpato (Alert fatigue)","text":"Ina maha rawa ngā whakatūpato, ka tīmata te tangata ki te whakahawea i a rātou, tae atu ki ērā e hira ana.","also":["ngenge whakatūpato","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Papa mātakitaki (Dashboard)","text":"He mata e whakaatu ana i ngā tau me ngā āhuatanga matua i te kitenga kotahi.","also":["papa mātakitaki","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Karanga ohorere (Paging)","text":"Te waea ohorere, te whakaoho rānei i te tangata e tūtei ana mō tētahi raru.","also":["karanga ohorere","paged"]},{"id":"escalation","g":"run","word":"Te piki ake (Escalation)","text":"Te kawe mai i tētahi he nui ake ōna pūkenga, tōna mana rānei, ina kore e taea te whakatika i te raru i te taumata o nāianei, kāore rānei i te tere.","also":["te piki ake","escalate","escalated"]},{"id":"triage","g":"run","word":"Kōmiri (Triage)","text":"Te kōmiri tere i ngā take e tae mai ana i runga i te ohorere me te hira, kia whakahaerehia tuatahitia te mea kino rawa.","also":["kōmiri","triaged"]},{"id":"impact","g":"run","word":"Pānga (Impact)","text":"Te nui o te pānga o tētahi mea ki ngā tāngata: tokohia, ā, pēhea te kino.","noTip":1},{"id":"urgency","g":"run","word":"Te ohorere (Urgency)","text":"Te hohoro me whakahaere tētahi mea. Mā te pānga me te ohorere tahi e whakatau te whakaarotau.","noTip":1},{"id":"plevels","g":"run","word":"Ngā taumata whakaarotau (P1, P2…)","text":"Ngā tapanga e whakaatu ana i te ohorere o tētahi take. Ko P1 te mea tino kino, me mahi tonu.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Rārangi tīkiti (Ticket queue)","text":"Te rārangi o ngā tono me ngā aituā e tatari ana kia tangohia.","also":["rārangi tīkiti","ticket queues"]},{"id":"tiers","g":"run","word":"Rārangi tuatahi me te rārangi tuarua (First line, second line)","text":"Ngā taumata tautoko: ka whakautu te rārangi tuatahi i te waea, ka whakatika i ngā mea māmā; he pūkenga hōhonu ake kei te rārangi tuarua mō ngā mea uaua. E kīia ana hoki he tier 1, he tier 2.","also":["rārangi tuatahi","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Kaiwhakahau aituā (Incident commander)","text":"Te tangata kotahi e ārahi ana i te urupare ki tētahi aituā, kia mōhio ai te katoa ko wai te kaiwhakatau, ko wai hoki e mahi ana i te aha.","also":["kaiwhakahau aituā","incident commanders"]},{"id":"responsetime","g":"run","word":"Wā urupare (Response time)","text":"Te roa tae noa ki te tango tuatahi a tētahi i tētahi tono, aituā rānei.","also":["wā urupare","response times"]},{"id":"resolution","g":"run","word":"Wā whakatika (Resolution time)","text":"Te roa ki te whakatika katoa i tētahi tono, aituā rānei, mai i te pūrongo tae noa ki te otinga.","also":["wā whakatika","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Wā toharite hei whakaora anō (Mean time to recover, MTTR)","text":"Hei toharite, te roa ki te whakahoki i tētahi ratonga kia mahi anō i muri i tana pakaru. He paku rerekē pea te tikanga o te MTTR, nō reira me kī he aha tāu e ine ana.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Wā toharite i waenga i ngā rahua (Mean time between failures, MTBF)","text":"Hei toharite, te roa e rere ai tētahi ratonga i mua i te pakaru o tētahi mea.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Pātengi raraunga whirihora (Configuration management database, CMDB)","text":"Te rārangi o ō tūemi whirihora katoa me te hono o tētahi ki tētahi, kia kitea ai he aha e whirinaki ana ki te aha.","also":["CMDB"]},{"id":"asset","g":"run","word":"Rawa (Asset)","text":"Tētahi mea whai uara kei a koe, e utua ana rānei hei whakahaere i te ratonga, pēnei i tētahi rorohiko pōnaho, i tētahi raihana pūmanawa, i tētahi ingoa rohe rānei.","also":["rawa","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Whakamahere āheinga (Capacity planning)","text":"Te whakarite kia rawaka te kaha rorohiko, te rokiroki me ngā tāngata mō ngā mea e haere mai ana.","also":["whakamahere āheinga","capacity plan"]},{"id":"scaling","g":"run","word":"Te whakawhānui (Scaling)","text":"Te manaaki i ngā kaiwhakamahi maha ake mā te hoatu i te kaha ake ki tētahi mīhini (scaling up), mā te tāpiri rānei i ētahi atu mīhini (scaling out).","also":["te whakawhānui","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Te haere tonu o te pakihi (Business continuity)","text":"Ngā mahere hei pupuri i ngā mea nui kia haere tonu ina tino hē tētahi mea nui, pēnei i te ngaro o tētahi tari, o tētahi kaiwhakarato matua, o ngā rorohiko rānei.","also":["te haere tonu o te pakihi","business continuity plan"]},{"id":"dr","g":"run","word":"Whakaoranga i te aituā nui (Disaster recovery, DR)","text":"Te mahere me ngā taputapu hei whakahoki mai i tētahi ratonga i muri i tētahi mea tino kino, pēnei i te ngaro o tētahi pokapū raraunga katoa.","also":["whakaoranga i te aituā nui","disaster recovery"]},{"id":"rto","g":"run","word":"Whāinga wā whakaora (Recovery time objective, RTO)","text":"Te roa rawa e āhei ai tētahi ratonga kia tū i muri i tētahi aituā nui, i mua i te wā me mahi anō.","also":["RTO"]},{"id":"rpo","g":"run","word":"Whāinga tohu whakaora (Recovery point objective, RPO)","text":"Te nui o ngā raraunga hou ka taea e koe te ngaro, e inea ana hei wā. Ki te kotahi hāora te RPO, me tārua ia hāora i te iti rawa.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Te tuarua (Redundancy)","text":"Te whai i ngā mea tuarua kua rite, pēnei i tētahi tūmau tuarua, kia kore ai e mutu te ratonga i te rahua kotahi.","also":["te tuarua"]},{"id":"failover","g":"run","word":"Whakawhiti ki te tuarua (Failover)","text":"Te huri ki tētahi pūnaha tuarua mā tōna anō ina rahua te mea noa.","also":["whakawhiti ki te tuarua","fail over"]},{"id":"spof","g":"run","word":"Wāhi rahua kotahi (Single point of failure)","text":"Te wāhanga kotahi ka hinga ngā mea katoa i a ia ina pakaru, nā te mea kāore he tuarua.","also":["wāhi rahua kotahi","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Matapihi tiaki (Maintenance window)","text":"He wā kua whakaritea e tārewa ai pea te ratonga, e pōturi ai rānei, mō te tiaki; ka whakamōhiotia ngā kaiwhakamahi i mua.","also":["matapihi tiaki","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Tuku mahi (Handover)","text":"Te tuku i te mahi, i te mātauranga me te kawenga ki tētahi atu tangata, rōpū rānei, kia kore ai tētahi mea e taka.","also":["tuku mahi","handovers"]},{"id":"kb","g":"run","word":"Pātaka mōhiotanga (Knowledge base)","text":"He kohinga tuhinga āwhina me ngā whakautu, mō ngā kaiwhakamahi me te rōpū.","also":["pātaka mōhiotanga","knowledge bases"]},{"id":"csat","g":"run","word":"Te makona o te kiritaki (Customer satisfaction, CSAT)","text":"He kaute mai i ngā kaiwhakamahi e kī ana i te nui o tō rātou koa, e pātaihia ana i te nuinga o te wā i muri i te katinga o tētahi tono.","also":["CSAT","te makona o te kiritaki"]},{"id":"supplier","g":"run","word":"Kaiwhakarato (Supplier)","text":"He kamupene o waho e whirinaki ana koe ki a ia, pēnei i tō kaiwhakarato manaaki tūmau. E kīia ana hoki he vendor, he third party rānei.","also":["kaiwhakarato","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Te whakamutu ratonga (Service retirement)","text":"Te whakaweto pūmau i tētahi ratonga i runga i te haumaru: te kōrero ki ōna kaiwhakamahi, te whakahaere i ōna raraunga me ōna urunga, me te whakamutu i ōna utu.","also":["te whakamutu ratonga","retiring a service"]},{"id":"eol","g":"run","word":"Mutunga oranga (End of life, EOL)","text":"Ina kore te hua e whiwhi whakahōu, tautoko rānei mai i tōna kaihanga, nō reira me whakakapi.","also":["EOL","end-of-life","mutunga oranga"]},{"id":"cybersec","g":"sec","word":"Haumaru ipurangi (Cybersecurity)","text":"Te tiaki i ngā pūnaha me ngā raraunga kei urutomohia, kei tāhaetia, kei whakangaromia rānei.","also":["haumaru ipurangi","cyber security"]},{"id":"authn","g":"sec","word":"Te whakamana tuakiri (Authentication)","text":"Te tirotiro ko wai tētahi, i te nuinga o te wā mā te kupuhipa, mā te waehere rānei. E poatohia ana hei authn.","also":["te whakamana tuakiri","authn"]},{"id":"authz","g":"sec","word":"Te whakaae urunga (Authorisation)","text":"Te tirotiro he aha ngā mea e whakaaetia ana kia mahia e tētahi, ina mōhio koe ko wai ia. E poatohia ana hei authz.","also":["te whakaae urunga","authz","authorization"]},{"id":"mfa","g":"sec","word":"Whakamana tuakiri maha-tohu (Multi-factor authentication, MFA)","text":"Te takiuru mā ngā taunakitanga e rua, neke atu rānei, pēnei i te kupuhipa me tētahi waehere i tō waea. E kīia ana hoki he two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","whakamana takirua"]},{"id":"sso","g":"sec","word":"Takiuru kotahi (Single sign-on, SSO)","text":"Te takiuru kotahi hei uru ki ngā pūnaha maha, pēnei i te whakamahi i tō pūkete mahi ki ngā wāhi katoa.","also":["SSO","takiuru kotahi"]},{"id":"pwmgr","g":"sec","word":"Kaiwhakahaere kupuhipa (Password manager)","text":"He taupānga e hanga ana i ngā kupuhipa kaha, e maumahara ana hoki mōu.","also":["kaiwhakahaere kupuhipa","password managers"]},{"id":"secret","g":"sec","word":"Mea muna (Secret)","text":"He kupuhipa, he kī, he waehere muna atu rānei ka whakamahia e tētahi hōtaka hei uru ki tētahi mea. Kaua rawa e tiritiria, e tuhia rānei ki te waehere.","also":["mea muna","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Kī API (API key)","text":"He waehere muna e āhei ai tētahi hōtaka ki te whakamahi i te API a tētahi atu ratonga, e whakaatu ana hoki ko wai e whakamahi ana (e utu ana hoki).","also":["kī API","API keys"]},{"id":"accesstoken","g":"sec","word":"Tohu urunga (Access token)","text":"He tohu urunga mō te wā poto e whakaatu ana kua whakaaetia te hōtaka kia uru, kia kore ai e hiahiatia tō kupuhipa i ia wā. Ehara i te rite ki te tohu AI (token).","also":["tohu urunga","access tokens"]},{"id":"encryption","g":"sec","word":"Whakamuna (Encryption)","text":"Te whakapōrearea i ngā mōhiohio kia pānuitia ai e te tangata anake kei a ia te kī tika.","also":["whakamuna","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Te huarahi haumaru e haere ai ngā whārangi tukutuku, e kitea ana mā te raka iti i tō pūtirotiro, kia kore ai e taea e tētahi i waenganui te pānui, te whakarerekē rānei."},{"id":"cert","g":"sec","word":"Tiwhikete SSL/TLS (SSL/TLS certificate)","text":"He kāri tuakiri matihiko e whakaatu ai tētahi pae tukutuku ko wai ia, ā, e āhei ai ki te whakamahi i a HTTPS. Ka pau tōna wā, nō reira me whakahōu.","also":["tiwhikete TLS","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Ngā whakaaetanga (Permissions)","text":"Ngā ture mō wai e āhei ana ki te kite, ki te whakarerekē rānei i te aha.","also":["ngā whakaaetanga","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Mana iti rawa (Least privilege)","text":"Te hoatu ki ia tangata, hōtaka rānei te urunga e tino hiahiatia ana anake, mō te roa e hiahiatia ana anake.","also":["mana iti rawa","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Whakahaere urunga i runga i te tūranga (Role-based access control, RBAC)","text":"Te hoatu i te urunga i runga i te tūranga, pēnei i te kaimātakitaki, i te kaiwhakatika rānei, kaua tangata ki te tangata.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Whakaraerae (Vulnerability)","text":"He ngoikoretanga ka taea e tētahi te whakamahi hei uru kino, hei whakakino rānei.","also":["whakaraerae","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Rā kore (Zero-day)","text":"He ngoikoretanga e mōhiotia ana e ngā kaiwhakaeke i mua i te whai wā o ngā kaihanga ki te whakatika.","also":["rā kore","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Pūmanawa kino (Malware)","text":"He pūmanawa kino, pēnei i ngā huaketo, i hangaia hei whakangaro, hei tūtei, hei tāhae rānei.","also":["pūmanawa kino"]},{"id":"ransomware","g":"sec","word":"Pūmanawa tono utu (Ransomware)","text":"He pūmanawa kino e raka ana i ō kōnae, ā, e tono moni ana hei wewete. Ko ngā kape tiaki pai te ārai pai rawa.","also":["pūmanawa tono utu","ransomware attack"]},{"id":"phishing","g":"sec","word":"Hī tinihanga (Phishing)","text":"Ngā karere teka e ngana ana ki te tinihanga i a koe kia tuku kupuhipa, moni rānei, kia whakatuwhera rānei i tētahi mea kino.","also":["hī tinihanga","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Tinihanga pāpori (Social engineering)","text":"Te tinihanga i ngā tāngata, kaua i ngā rorohiko, kia hoatu e rātou he urunga, pēnei i tētahi waea teka mai i “te tautoko IT”."},{"id":"firewall","g":"sec","word":"Pakitara ahi (Firewall)","text":"He kaitiaki e whakatau ana ko ēhea raraunga whatunga e āhei ana ki te uru mai, ki te puta atu rānei.","also":["pakitara ahi","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"He kupu poto mō virtual private network: he hononga muna, kua whakamunatia, mā te ipurangi, e whakamahia ana hei uru haumaru ki ngā pūnaha mahi.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Te aukati ratonga (Denial of service, DoS, DDoS)","text":"Te waipuke i tētahi ratonga ki te nui rawa o ngā tono teka kia kore ai e taea e ngā tāngata tūturu te whakamahi. Ko te tikanga o DDoS, ka ahu mai i ngā rorohiko maha i te wā kotahi.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Whakamātau uru (Penetration test, pen test)","text":"Te utu i ngā tohunga pai kia ngana ki te uru, kia kitea ai ngā ngoikoretanga i mua i te kitenga a ngā kaiwhakaeke tūturu.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Arotake haumaru (Security audit)","text":"He tirotiro tūpato mō te pai o te tiaki i tētahi mea, e whakatauritea ana ki tētahi rārangi tikanga pai.","also":["arotake haumaru","security audits"]},{"id":"threatmodel","g":"sec","word":"Te whakatauira mōrearea (Threat modelling)","text":"Te āta whakaaro ko wai pea ka whakaeke i tētahi mea, me pēhea, ā, he aha tāu e mahi ai hei aukati i a rātou.","also":["te whakatauira mōrearea","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Pakaru raraunga (Data breach)","text":"Ina rere ngā mōhiohio muna ki te hunga kāore e tika kia whiwhi, ina ngaro rānei, ina whakarerekētia rānei me te kore whakaaetanga.","also":["pakaru raraunga","data breaches"]},{"id":"pii","g":"sec","word":"Raraunga whaiaro (Personal data)","text":"Ngā mōhiohio mō tētahi tangata ka taea te tautohu, pēnei i te ingoa, i te wāhitau īmēra, i te wāhi rānei. E kīia ana hoki he PII.","also":["raraunga whaiaro","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Te ture a Ūropi mō ngā raraunga whaiaro (he putanga ake tō Piritene): kohia ngā mea e hiahiatia ana anake, kia haumaru te pupuri, ā, tukua te tangata kia kite, kia muku rānei i ōna ake raraunga.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Tiaki raraunga (Data protection)","text":"Te tiaki tika i ngā raraunga whaiaro i raro i te ture.","also":["tiaki raraunga","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Kaupapahere noho muna (Privacy policy)","text":"He whārangi tūmatanui e kī ana he aha ngā raraunga whaiaro e kohia ana e koe, he aha te take, me tāu e mahi ai ki aua raraunga.","also":["kaupapahere noho muna","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Whakaaetanga (Consent)","text":"Te “āe” mārama, herekore o te tangata kia whakamahia ōna raraunga i tētahi tikanga motuhake. Ka taea e ia te tango atu i ngā wā katoa.","also":["whakaaetanga","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Kuki (Cookie)","text":"He kōnae iti ka penapenatia e tētahi pae tukutuku ki tō pūtirotiro hei maumahara i ētahi mea, pēnei i tō takiuru. Mō ētahi, me whakaae koe i te tuatahi.","also":["kuki","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Te whakaiti raraunga (Data minimisation)","text":"Te kohi me te pupuri i ngā raraunga whaiaro e tino hiahiatia ana anake mō te mahi.","also":["te whakaiti raraunga","data minimization"]},{"id":"retention","g":"sec","word":"Te pupuri raraunga (Data retention)","text":"Te roa e pupuritia ai ngā raraunga i mua i te mukunga. Ko te kore e pupuri roa ake i te wā e hiahiatia ana he haumaru ake, ā, he ture hoki i te nuinga o te wā.","also":["te pupuri raraunga","retention period"]},{"id":"anon","g":"sec","word":"Whakangaro tuakiri (Anonymisation)","text":"Te whakarerekē i ngā raraunga kia kore ai e taea te tautohu i tētahi tangata i aua raraunga.","also":["whakangaro tuakiri","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Whakakapi ingoa (Pseudonymisation)","text":"Te whakakapi i ngā ingoa me ētahi atu taipitopito ki ngā waehere, me tētahi kī e puritia wehe ana hei hono anō. He raraunga whaiaro tonu ēnei.","also":["whakakapi ingoa","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Whakaaetanga tukatuka raraunga (Data processing agreement, DPA)","text":"He kirimana e kī ana me pēhea e whakahaere ai te kaiwhakarato i ngā raraunga whaiaro hei mahi mōu.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Aromatawai pānga tiaki raraunga (Data protection impact assessment, DPIA)","text":"He tirohanga tūpato i mua i te tīmata, mō te pānga o tētahi mahere whakamahi raraunga whaiaro ki ngā tāngata, me te āhua o te whakaiti i ngā tūraru.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Rātaka arotake (Audit log)","text":"He rekoata o te mahi a wai, he aha, āhea hoki, kia taea ai te tirotiro i ngā mahi a muri ake.","also":["rātaka arotake","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Te whai i ngā ture (Compliance)","text":"Te whai i ngā ture, ngā ture ā-tikanga me ngā paerewa e pā ana ki a koe, me te āhei ki te whakaatu e pērā ana koe.","also":["te whai i ngā ture","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"He paerewa ao rongonui mō te whakahaere i te haumaru mōhiohio. Ka taea e ngā kamupene te whiwhi tiwhikete i raro i a ia.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"He pūrongo Amerika, kua tirohia e ngā kaitātari o waho, e whakaatu ana e tiaki tika ana te kamupene i ngā raraunga kiritaki.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"He AI e mahi ana i tētahi mahi mā tōna anō: ka pānui i te waehere, ka whakarerekē, ka whakahaere i ngā tirotiro, ā, ka pūrongo mai. Ka tirohia tonutia tāna mahi.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Ngā wāhanga kuputuhi iti e pānuitia ana, e tuhia ana e te AI, tata ki te toru hauwhā o te kupu ia wāhanga. E tatauria ana te whakamahinga AI ki ngā token, nō reira ina iti ngā token, ka toe te nui ake o tō mahere.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"He whakahau iti ka rere mā tōna anō i tētahi wā kua whakaritea, hei tauira ina tīmata tētahi nohoanga AI, kia rongo ai te rōpū i ō kōrero.","also":["hooks"]},{"id":"ai","g":"ai","word":"Atamai horihori (Artificial intelligence, AI)","text":"Ngā pūnaha rorohiko e mahi ana i ngā mea e whakaaro ana tātou me he tangata hei mahi, pēnei i te tuhi, te whakautu pātai, te tautohu pikitia rānei.","also":["AI","artificial intelligence","atamai horihori","atamai hangahanga"],"noTip":1},{"id":"ml","g":"ai","word":"Te ako a te mīhini (Machine learning, ML)","text":"He tikanga e ako ai ngā rorohiko i ngā hanga auau mai i ngā tauira tini, kaua ko te hoatu ture tōtika ki a rātou.","also":["te ako a te mīhini","machine learning"]},{"id":"model","g":"ai","word":"Tauira (Model)","text":"Te “roro” kua whakangungua o tētahi pūnaha AI, i hangaia mā te ako i ngā tauira tino maha. He rerekē ngā tauira i te pūkenga, i te tere, i te utu hoki.","also":["tauira","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Tauira reo nui (Large language model, LLM)","text":"He tauira AI i whakangungua ki te nui rawa o ngā kuputuhi, nō reira ka taea e ia te pānui me te tuhi i te reo.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI waihanga (Generative AI)","text":"He AI e waihanga ana i ngā mea hou, pēnei i te kuputuhi, i ngā pikitia, i te waehere rānei, kaua ko te kōmaka, te kite noa rānei.","also":["AI waihanga","GenAI"]},{"id":"chatbot","g":"ai","word":"Karetao kōrero (Chatbot)","text":"He hōtaka ka kōrero koe ki a ia i te reo o ia rā, mā te patopato, mā te kōrero rānei.","also":["karetao kōrero","chatbots"]},{"id":"prompt","g":"ai","word":"Tohutohu (Prompt)","text":"Te mea e hoatu ana e koe ki te AI: tō pātai, ō tohutohu rānei, me ngā mea katoa ka hoatu e koe. Ko ngā tohutohu mārama ake ka whiwhi whakautu pai ake i te nuinga o te wā.","also":["tohutohu","prompts"]},{"id":"prompteng","g":"ai","word":"Te tuhi tohutohu (Prompt engineering)","text":"Te pūkenga ki te tuhi tohutohu e puta ai he hua pono, he hua whai take.","also":["te tuhi tohutohu"]},{"id":"sysprompt","g":"ai","word":"Tohutohu pūnaha (System prompt)","text":"Ngā tohutohu papamuri ka whiwhi te AI i mua i te tīmatanga o te kōrerorero, e whakatau ana i tōna tūranga me ōna ture. He nui ake tō rātou mana i tāu e patopato ai.","also":["tohutohu pūnaha","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Horopaki (Context)","text":"Ngā mea katoa ka kitea e te AI i a ia e mahi ana: ngā tohutohu, ō karere, ngā kōnae kua pānuitia e ia me ngā whakautu o mua.","noTip":1},{"id":"ctxwin","g":"ai","word":"Matapihi horopaki (Context window)","text":"Te nui ka taea e te AI te pupuri i te hinengaro i te wā kotahi, e inea ana hei tohu (token). Ki te nui atu, ka whakarerea, ka whakarāpopototia rānei ngā wāhanga tawhito.","also":["matapihi horopaki","context windows"]},{"id":"session","g":"ai","word":"Nohoanga (Session)","text":"Kotahi te kōrerorero mahi me te AI, mai i te tīmatanga ki te mutunga. Ka tīmata te nohoanga hou me te maumahara ātea.","also":["nohoanga","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Maumahara (Memory)","text":"Ngā tuhipoka ka puritia e te AI i waenga i ngā nohoanga, kia mahara ai ia ki ō hiahia me ngā whakatau o mua.","noTip":1},{"id":"hallucination","g":"ai","word":"Pohewa (Hallucination)","text":"Ina kī te AI i tētahi mea me te āhua tino māia, engari he mea hanga noa, he hē rānei. Tirohia ngā meka hira.","also":["pohewa","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Whakangungu (Training)","text":"Te whakaako i tētahi tauira mā te whakaatu i ngā tauira tino maha ki a ia, i mua i te whakamahinga e tētahi.","also":["whakangungu","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Raraunga whakangungu (Training data)","text":"Ngā tauira i ako ai te tauira AI. Ka mutu tōna mōhio i te rā i kohia ai aua raraunga.","also":["raraunga whakangungu","training set"]},{"id":"cutoff","g":"ai","word":"Rā mutunga mōhio (Knowledge cutoff)","text":"Te rā ka mutu te mōhio kua hangaia ki roto i te AI. Kāore ia e mōhio ki ngā mea o muri mai, ki te kore ia e rapu.","also":["rā mutunga mōhio","training cutoff"]},{"id":"finetune","g":"ai","word":"Whakangungu whāiti (Fine-tuning)","text":"Te whakangungu tāpiri i tētahi tauira kua oti kē ki ō ake tauira, kia pai ake ai ia ki tētahi mahi motuhake.","also":["whakangungu whāiti","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Te whakamahi tauira (Inference)","text":"Ka whakamahia tūturutia te tauira AI hei whakautu i tētahi mea, kaua ko te whakangungu.","also":["te whakamahi tauira","model inference"]},{"id":"tooluse","g":"ai","word":"Whakamahi taputapu (Tool use)","text":"Te āhei o te AI ki te mahi i ngā mea, kaua e kōrero noa: whakahaere i ngā whakahau, pānui kōnae, rapu tukutuku rānei, mā ngā taputapu ka hoatu e te taupānga.","also":["whakamahi taputapu","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Kaiwhakahaere tuarua (Subagent)","text":"He AI āwhina ka hoatu e tētahi AI matua he mahi iti ake ki a ia, ā, ka whakahokia mai e ia te hua.","also":["kaiwhakahaere tuarua","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Kaiwhakahaere maha (Multi-agent)","text":"He maha ngā AI e mahi tahi ana i tētahi mahi kotahi, he wāhanga tō ia AI, pēnei i tētahi rōpū iti.","also":["kaiwhakahaere maha","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Mana motuhake (Autonomy)","text":"Te nui o ngā mea ka taea e te AI te mahi mā tōna anō i mua i tana pātai ki tētahi tangata.","also":["mana motuhake","autonomous"]},{"id":"hitl","g":"ai","word":"Te tangata i roto i te porowhita (Human in the loop)","text":"Te whakauru tonu i tētahi tangata hei tirotiro, hei whakaae rānei i ngā mahi a te AI i ngā wā matua. I roto i a AI-gile, ko koe tērā.","also":["te tangata i roto i te porowhita","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Taiapa tiaki (Guardrails)","text":"Ngā here me ngā tirotiro e pupuri ana i ngā mahi a te AI kia haumaru, pēnei i te whakaaetanga e hiahiatia ana i mua i te haere ora o tētahi mea. Ka whakaiti i te tūraru o ngā hapa, engari kāore e whakakore katoa.","also":["taiapa tiaki","guardrail"]},{"id":"rag","g":"ai","word":"Waihanga ā-rapu (Retrieval-augmented generation, RAG)","text":"Te tuku i te AI kia rapu i roto i ō ake tuhinga i mua i te whakautu, kia tū ai āna whakautu ki runga i ō meka.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Tohu tikanga ā-tau (Embedding)","text":"Te huri i te kuputuhi hei rārangi tau e mau ana i tōna tikanga, kia kitea ai e te rorohiko ngā mea he rite te tikanga.","also":["tohu tikanga ā-tau","embeddings"]},{"id":"vectordb","g":"ai","word":"Pātengi raraunga vector (Vector database)","text":"He pātengi raraunga i hangaia hei rapu i aua rārangi tau (embeddings), hei kimi i ngā mea he rite te tikanga.","also":["pātengi raraunga vector","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Kawa horopaki tauira (Model Context Protocol, MCP)","text":"He tikanga paerewa hei hono i ngā taputapu me ngā puna raraunga ki ngā taupānga AI, kia taea e te AI te whakamahi.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Pāmahana (Temperature)","text":"He tautuhinga mō te māia o ngā whakautu a te AI. Ko te iti ka hoatu he whakautu pūmau ake, māmā ake te matapae; ko te teitei ka hoatu he whakautu rerekē ake. Ahakoa iti, ahakoa teitei, kāore e tika tonu ai ia.","also":["pāmahana","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Maha-momo (Multimodal)","text":"Ka taea te mahi ki ngā momo mōhiohio maha, pēnei i te kuputuhi, i ngā pikitia me te oro.","also":["maha-momo","multi-modal"]},{"id":"evals","g":"ai","word":"Aromatawai (Evaluation, eval)","text":"He whakamātau kua whakaritea mō te pai o te mahi a te AI ki ngā tauira kua tīpakohia, kia whakatauritea ai ngā tauira, ngā prompt rānei.","also":["aromatawai","eval","evals"]},{"id":"bias","g":"ai","word":"Tītaha (Bias)","text":"Ina tītaha tētahi AI (he tangata rānei) ki tētahi taha, kāore i te tika, i te nuinga o te wā nā ngā mea i ako ai ia.","also":["tītaha","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI haepapa (Responsible AI)","text":"Te whakamahi i te AI i runga i te tika, te haumaru me te pono, ā, ko te tangata tonu te haepapa mō ngā hua.","also":["AI haepapa","ethical AI"]},{"id":"injection","g":"ai","word":"Kuhu tohutohu (Prompt injection)","text":"He tinihanga e ngana ai ngā tohutohu huna i tētahi whārangi tukutuku, i tētahi kōnae rānei, kia mahia e te AI tētahi mea kāore i tonoa e tōna kaiwhakamahi.","also":["kuhu tohutohu","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Tepe tere (Rate limit)","text":"He tepe mō te maha o ngā tono ka tukuna ki tētahi ratonga i tētahi wā kua whakaritea. Ki te neke atu, me tatari koe.","also":["tepe tere","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Tepe whakamahi (Usage limit)","text":"Te nui o te mahi AI e whakaaetia ana e tō mahere i tētahi wā; i muri, ka tārewa, ka nui ake rānei te utu.","also":["tepe whakamahi","usage limits"]},{"id":"vibe","g":"ai","word":"Tuhi waehere ā-ngākau (Vibe coding)","text":"Te hanga pūmanawa, te nuinga mā te whakamārama i tāu e hiahia ana ki te AI, ā, mā te AI e tuhi te waehere.","also":["tuhi waehere ā-ngākau","vibe-coding"]},{"id":"budget","g":"money","word":"Tahua (Budget)","text":"Te nui o te moni kua wehea mō tētahi mea.","also":["tahua","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Whakatau tata utu (Cost estimate)","text":"He matapae pai rawa mō te utu o tētahi mea i mua i te tīmata.","also":["whakatau tata utu","cost estimates"]},{"id":"roi","g":"money","word":"Hua whakahoki haumi (Return on investment, ROI)","text":"Te mea ka hoki mai ki a koe ina whakatauritea ki tāu i whakapau ai. Mēnā he tōrunga, i whai take.","also":["ROI","hua whakahoki haumi"]},{"id":"tco","g":"money","word":"Utu tapeke o te pupuri (Total cost of ownership, TCO)","text":"Te utu tūturu katoa o tētahi mea puta noa i tōna oranga, kaua ko te utu hoko anake: te whakahaere, te tautoko, ngā whakahōunga, ā, hei whakamutunga, te whakamutu.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx me OpEx","text":"Ko CapEx te moni e whakapaua ana i te tīmatanga mō ngā mea e pupuri ana koe; ko OpEx te whakapaunga haere tonu, pēnei i ngā nama ia marama.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Ohaurunga (Subscription)","text":"Te utu auau, i te nuinga o te wā ia marama, ia tau rānei, kia whakamahi tonu ai i tētahi mea.","also":["ohaurunga","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Pūmanawa hei ratonga (Software as a service, SaaS)","text":"Te pūmanawa e whakamahia ana e koe ki runga ipurangi, ā, e utua ana mā te ohaurunga, ā, mā te kaihanga e whakahaere mōu.","also":["SaaS","pūmanawa hei ratonga"]},{"id":"payg","g":"money","word":"Utu i tāu e whakamahi ai (Pay as you go)","text":"Te utu mō tāu i whakamahi ai anake, pēnei i te rorohiko kapua, i ngā tohu AI rānei.","also":["utu i tāu e whakamahi ai","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Whakamahinga tāpiri (Overage)","text":"Te whakamahi neke atu i ngā mea kei roto i tō mahere, ā, ka nui ake pea te utu.","also":["whakamahinga tāpiri","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Whakatūpato nama (Billing alert)","text":"He karere ina tae te whakapaunga, te whakamahinga rānei ki tētahi taumata i tīpakohia e koe. Ka whakatūpato i a koe, engari kāore i te mea ka aukatia ngā utu tāpiri i ngā wā katoa.","also":["whakatūpato nama","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Taumata koreutu (Free tier)","text":"He taumata koreutu o tētahi ratonga utu, he here tōna. He pai mō te tīmata.","also":["taumata koreutu","free plan"]},{"id":"pricing","g":"money","word":"Mahere utu (Pricing plan)","text":"Ngā kete rerekē e hokona ana e tētahi ratonga, he utu, he here tō ia kete.","also":["mahere utu","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Raihana (Licence)","text":"Ngā ture mō te whakamahi, te tārua, te whakarerekē, te tiritiri rānei i tā tētahi atu i hanga ai, pēnei i te pūmanawa, i ngā momotuhi, i ngā pikitia rānei.","also":["raihana","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Pūtake tuwhera (Open source)","text":"Te pūmanawa ka taea e te katoa te pānui i tōna waehere, te whakamahi, ā, i te nuinga o te wā, te whakarerekē mō te kore utu, i raro i ngā ture o tōna raihana.","also":["pūtake tuwhera","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Raihana pūtake tuwhera (Open source licence)","text":"Ngā ture e haere tahi ana me te waehere pūtake tuwhera. Ka whakaae ētahi kia tata mahi koe i ngā mea katoa (pēnei i a MIT); ka tono ētahi kia tiritiri hoki koe i ō rerekētanga (pēnei i a GPL).","also":["raihana pūtake tuwhera","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Tūmataiti (Proprietary)","text":"Nā tētahi kamupene, ā, kāore e wātea kia tāruatia, kia whakarerekētia rānei. Te tauaro o te pūtake tuwhera.","also":["tūmataiti","proprietary software"]},{"id":"copyright","g":"money","word":"Manatārua (Copyright)","text":"Te mana ture o te kaihanga ki te whakahaere i ngā tārua o tāna mahi, tae atu ki te waehere me ngā tuhinga.","also":["manatārua","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Rawa hinengaro (Intellectual property, IP)","text":"Ngā whakaaro me ngā mahi auaha e kīia ana e te ture he mea whai rangatira, pēnei i te waehere, i ngā hoahoa, i ngā ingoa me ngā tohu.","also":["rawa hinengaro","intellectual property"]},{"id":"tos","g":"money","word":"Ngā here ratonga (Terms of service)","text":"Ngā ture e whakaae ai koe ina whakamahi koe i tētahi ratonga.","also":["ngā here ratonga","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Kirimana (Contract)","text":"He whakaaetanga tuhi i waenga i ngā taha e rua ka tautokona e te ture.","also":["kirimana","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Tauākī mahi (Statement of work, SOW)","text":"He tuhinga e whakatakoto tika ana he aha te mahi ka mahia, āhea ka oti, e hia hoki te utu.","also":["SOW","tauākī mahi"]},{"id":"fixedprice","g":"money","word":"Utu pūmau (Fixed price)","text":"He utu kua whakaaetia mō te mahi katoa, ahakoa te roa.","also":["utu pūmau","fixed-price"]},{"id":"tm","g":"money","word":"Wā me ngā rawa (Time and materials)","text":"Te utu mō ngā hāora i tino mahia me ngā mea i tino whakamahia, kaua ko tētahi utu kua whakaritea.","also":["wā me ngā rawa","T&M"]},{"id":"invoice","g":"money","word":"Pire (Invoice)","text":"He tono utu ā-tuhi mō te mahi kua oti, mō ngā taonga kua tukuna rānei.","also":["pire","nama","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Te mauhere ki te kaiwhakarato (Vendor lock-in)","text":"Ina tino uaua, tino utu nui rānei te wehe atu i tētahi kaiwhakarato, ā, ka mau tonu koe ki a ia.","also":["te mauhere ki te kaiwhakarato","lock-in"]},{"id":"procurement","g":"money","word":"Te hoko rawa (Procurement)","text":"Te tukanga o te kōwhiri me te hoko mai i ngā kaiwhakarato.","also":["te hoko rawa"]},{"id":"servicecredit","g":"money","word":"Utu whakahoki ratonga (Service credit)","text":"Te whakahoki moni, te heke utu rānei ka whiwhi koe ina kore te kaiwhakarato e tutuki i tana SLA.","also":["utu whakahoki ratonga","service credits"]}]}};
